begin;

-- This is the sole baseline migration for KEYFORTA's PostgreSQL schema,
-- consolidating former migrations 0001-0036 into one file before any
-- production tenant data existed (see ADR-013 amendment, 2026-09-27). It
-- was generated by applying every prior migration to a fresh PostgreSQL 16
-- database and taking a schema-only pg_dump of the result, then hand-adding
-- the role-provisioning prelude below (which the prior 0001/0030 migrations
-- and application code split across migrate.ts previously handled). From
-- this point forward, ADR-013's forward-only rule applies unchanged: this
-- file itself must never be edited once any environment has recorded its
-- checksum; all further schema changes are new, additive migration files.

do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'keyforta_runtime') then
    create role keyforta_runtime nologin nosuperuser nocreatedb nocreaterole noinherit;
  end if;
exception
  when duplicate_object or unique_violation then
    null;
end
$$;

-- keyforta_media_review_admin owns three SECURITY DEFINER functions that
-- need cross-organization visibility for moderation (see the RLS policies
-- and grants below). It intentionally has no BYPASSRLS: Azure Database for
-- PostgreSQL Flexible Server never grants BYPASSRLS to a Microsoft Entra
-- (managed-identity) admin, so a role that depended on it could never be
-- created there. Cross-organization visibility instead comes entirely from
-- the additive `to keyforta_media_review_admin` RLS policies dumped below.
do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'keyforta_media_review_admin') then
    create role keyforta_media_review_admin nologin nosuperuser nocreatedb nocreaterole noinherit;
  end if;
exception
  when duplicate_object or unique_violation then
    null;
end
$$;

-- The functions below use `alter function ... owner to
-- keyforta_media_review_admin`, which PostgreSQL only allows when the
-- connecting role is itself a member of the target role (superuser
-- exempted, which no Azure customer connection ever is). Grant plain,
-- non-inheriting membership to whichever role is actually running this
-- migration -- this varies per environment (a differently named managed
-- identity in each), so it must be resolved dynamically via current_user
-- rather than hardcoded. Membership is deliberately *not* inherited:
-- `alter ... owner to` only ever needs membership, not inherited
-- privilege, and granting inherited privilege here would let every other
-- SECURITY DEFINER function this identity owns also satisfy the RLS
-- policies' `to keyforta_media_review_admin` clause for as long as the
-- grant exists, far beyond the three functions actually reassigned here.
do $$
begin
  execute format('grant keyforta_media_review_admin to %I', current_user);
exception
  when duplicate_object then
    null;
end
$$;

-- `alter ... owner to` additionally requires the *new* owner to hold
-- CREATE privilege on the object's schema (not just USAGE), so this must
-- run before the `alter function ... owner to keyforta_media_review_admin`
-- statements further down reassign ownership of the three admin functions.
grant create on schema app to keyforta_media_review_admin;

SET LOCAL check_function_bodies = false;

--
-- Name: btree_gist; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA public;

--
-- Name: EXTENSION btree_gist; Type: COMMENT; Schema: -; Owner: 
--

COMMENT ON EXTENSION btree_gist IS 'support for indexing common datatypes in GiST';

--
-- Name: pgcrypto; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;

--
-- Name: EXTENSION pgcrypto; Type: COMMENT; Schema: -; Owner: 
--

COMMENT ON EXTENSION pgcrypto IS 'cryptographic functions';

