    'declined'
);

CREATE FUNCTION app.accept_membership_invitation(requested_token_hash text, requested_subject text, requested_email text, requested_display_name text, requested_correlation_id text) RETURNS TABLE(invitation_id uuid, organization_id uuid, user_id uuid, role app.organization_role, accepted_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
declare
  invitation app.membership_invitations%rowtype;
  accepted_user app.users%rowtype;
  trusted_organization_id uuid;
  accepted_timestamp timestamptz;
begin
  if requested_subject is null or length(trim(requested_subject)) = 0
    or requested_email is null or length(trim(requested_email)) = 0
    or requested_correlation_id is null or length(trim(requested_correlation_id)) = 0 then
    raise exception 'verified identity and correlation are required';
  end if;

  select token.organization_id into trusted_organization_id
  from app.membership_invitation_tokens as token
  where token.token_hash = requested_token_hash;

  if not found then
    return;
  end if;

  perform set_config('app.organization_id', trusted_organization_id::text, true);

  select candidate.* into invitation
  from app.membership_invitations as candidate
  where candidate.token_hash = requested_token_hash
  for update;

  if not found
    or invitation.accepted_at is not null
    or invitation.revoked_at is not null
    or invitation.expires_at <= now()
    or invitation.recipient_email <> lower(trim(requested_email)) then
    return;
  end if;

  insert into app.users (external_subject, display_name)
  values (trim(requested_subject), coalesce(nullif(trim(requested_display_name), ''), lower(trim(requested_email))))
  on conflict (external_subject) do update
    set display_name = excluded.display_name
  returning * into accepted_user;

  accepted_timestamp := transaction_timestamp();
  update app.memberships
  set active = false,
      effective_to = accepted_timestamp
  where memberships.organization_id = invitation.organization_id
    and memberships.user_id = accepted_user.id
    and memberships.active
    and memberships.effective_from < accepted_timestamp
    and (
      memberships.effective_to is null
      or accepted_timestamp < memberships.effective_to
    );

  insert into app.memberships (
    organization_id, user_id, role, active, effective_from
  ) values (
    invitation.organization_id, accepted_user.id, invitation.role, true,
    accepted_timestamp
  );

  update app.membership_invitations
  set accepted_at = accepted_timestamp, accepted_by_user_id = accepted_user.id
  where id = invitation.id
  returning membership_invitations.accepted_at into accepted_at;

  insert into app.audit_events (
    organization_id, actor_id, correlation_id, action, entity_type, entity_id
  ) values (
    invitation.organization_id, accepted_user.id, requested_correlation_id,
    'invitation.accepted', 'membership_invitation', invitation.id
  );

  invitation_id := invitation.id;
  organization_id := invitation.organization_id;
  user_id := accepted_user.id;
  role := invitation.role;
  return next;
end
$$;

CREATE FUNCTION app.activate_jurisdiction_policy(requested_policy_version_id uuid, requested_owner_evidence_id uuid, requested_counsel_evidence_id uuid, requested_effective_from timestamp with time zone, requested_effective_to timestamp with time zone, requested_activated_by_user_id uuid, requested_correlation_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
declare
  policy app.jurisdiction_policy_versions%rowtype;
  created_activation_id uuid;
begin
  if requested_effective_from is null
    or (requested_effective_to is not null and requested_effective_to <= requested_effective_from)
    or requested_correlation_id is null
    or length(btrim(requested_correlation_id)) = 0 then
    raise exception 'valid activation interval and correlation are required';
  end if;

  select candidate.* into policy
  from app.jurisdiction_policy_versions as candidate
  where candidate.id = requested_policy_version_id;

  if not found then
    raise exception 'policy version not found';
  end if;

  if not exists (
    select 1
    from app.policy_approval_evidence as evidence
    where evidence.id = requested_owner_evidence_id
      and evidence.policy_version_id = policy.id
      and evidence.approval_role = 'policy_owner'
      and not exists (
        select 1 from app.policy_approval_revocations as revocation
        where revocation.approval_evidence_id = evidence.id
      )
  ) then
    raise exception 'valid policy owner approval is required';
  end if;

  if policy.requires_counsel_approval and not exists (
    select 1
    from app.policy_approval_evidence as evidence
    where evidence.id = requested_counsel_evidence_id
      and evidence.policy_version_id = policy.id
      and evidence.approval_role = 'qualified_counsel'
      and not exists (
        select 1 from app.policy_approval_revocations as revocation
        where revocation.approval_evidence_id = evidence.id
      )
  ) then
    raise exception 'qualified counsel approval is required';
  end if;

  insert into app.jurisdiction_policy_activations (
    policy_version_id, policy_key, jurisdiction_code,
    owner_evidence_id, counsel_evidence_id,
    effective_from, effective_to, activated_by_user_id, correlation_id
  ) values (
    policy.id, policy.policy_key, policy.jurisdiction_code,
    requested_owner_evidence_id, requested_counsel_evidence_id,
    requested_effective_from, requested_effective_to,
    requested_activated_by_user_id, requested_correlation_id
  ) returning id into created_activation_id;

  return created_activation_id;
end
$$;

CREATE FUNCTION app.actor_can_manage_property(requested_organization_id uuid, requested_property_id uuid, requested_actor_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
  select
    app.actor_is_active_landlord(requested_organization_id, requested_actor_id)
    or exists (
      select 1
      from app.manager_property_assignments as assignment
      join app.memberships as membership
        on membership.organization_id = assignment.organization_id
        and membership.user_id = assignment.manager_user_id
      where assignment.organization_id = requested_organization_id
        and assignment.property_id = requested_property_id
        and assignment.manager_user_id = requested_actor_id
        and assignment.revoked_at is null
        and membership.role in ('landlord', 'manager')
        and membership.active
        and membership.effective_from <= transaction_timestamp()
        and (
          membership.effective_to is null
          or transaction_timestamp() < membership.effective_to
        )
    )
$$;

CREATE FUNCTION app.actor_can_upload_public_listing_image(requested_listing_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  listing app.public_listings%rowtype;
begin
  if organization is null or actor is null then
    raise exception 'trusted request context is required';
  end if;

  select * into listing
  from app.public_listings
  where organization_id = organization and id = requested_listing_id;

  if not found then
    return false;
  end if;

  return app.actor_can_manage_property(organization, listing.property_id, actor);
end
$$;

CREATE FUNCTION app.actor_is_active_landlord(requested_organization_id uuid, requested_actor_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
  select exists (
    select 1
    from app.memberships
    where organization_id = requested_organization_id
      and user_id = requested_actor_id
      and role = 'landlord'
      and active
      and effective_from <= transaction_timestamp()
      and (effective_to is null or transaction_timestamp() < effective_to)
  )
$$;

CREATE FUNCTION app.add_rental_unit(requested_property_id uuid, requested_label text, requested_canonical_label text, requested_unit_type text, requested_bedrooms smallint, requested_bathrooms smallint, requested_area_square_meters integer, requested_floor_label text, requested_furnishing_status text, requested_idempotency_key text, requested_correlation_id text, requested_source text) RETURNS TABLE(unit_id uuid, unit_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := coalesce(requested_correlation_id, nullif(current_setting('app.correlation_id', true), ''));
  property_record app.properties%rowtype;
  created_unit app.units%rowtype;
  payload jsonb;
  replay record;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  select * into property_record
  from app.properties
  where organization_id = organization and id = requested_property_id
  for update;

  if not found or property_record.archived_at is not null then
    raise exception 'the requested Property was not found' using errcode = 'P0002';
  end if;

  if not app.actor_can_manage_property(organization, requested_property_id, actor) then
    raise exception 'the actor is not authorized to manage this Property' using errcode = '42501';
  end if;

  payload := jsonb_build_object(
    'propertyId', requested_property_id, 'label', requested_label,
    'unitType', requested_unit_type, 'bedrooms', requested_bedrooms,
    'bathrooms', requested_bathrooms, 'areaSquareMeters', requested_area_square_meters,
    'floorLabel', requested_floor_label, 'furnishingStatus', requested_furnishing_status
  );

  select * into replay from app.resolve_rental_inventory_creation_replay(
    organization, actor, 'add_rental_unit', requested_idempotency_key, payload
  );

  if replay.is_replay then
    unit_id := (replay.replay_result ->> 'unitId')::uuid;
    unit_version := (replay.replay_result ->> 'unitVersion')::integer;
    return next;
    return;
  end if;

  insert into app.units (
    organization_id, property_id, label, canonical_label, unit_type, bedrooms,
    bathrooms, area_square_meters, floor_label, furnishing_status,
    availability_status, publication_status, version
  ) values (
    organization, requested_property_id, requested_label,
    requested_canonical_label, requested_unit_type, requested_bedrooms,
    requested_bathrooms, requested_area_square_meters, requested_floor_label,
    requested_furnishing_status, 'unavailable', 'draft', 1
  ) returning * into created_unit;

  insert into app.unit_availability_versions (
    organization_id, unit_id, status, reason_code, effective_from, created_by,
    correlation_id, source
  ) values (
    organization, created_unit.id, 'unavailable', 'not_yet_available',
    transaction_timestamp(), actor, correlation, requested_source
  );

  perform app.record_rental_inventory_event(
    organization, 'unit', created_unit.id, created_unit.version, actor,
    correlation, 'unit.created', null, requested_source
  );

  unit_id := created_unit.id;
  unit_version := created_unit.version;

  perform app.record_rental_inventory_creation_replay(
    organization, actor, 'add_rental_unit', requested_idempotency_key, payload,
    jsonb_build_object('unitId', unit_id, 'unitVersion', unit_version)
  );

  return next;
end
$$;

CREATE FUNCTION app.archive_rental_property(requested_property_id uuid, requested_reason text, requested_expected_version integer, requested_idempotency_key text, requested_correlation_id text, requested_source text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := coalesce(requested_correlation_id, nullif(current_setting('app.correlation_id', true), ''));
  property_record app.properties%rowtype;
  blocking_lease_count integer;
  occupied_unit_count integer;
  unit_row app.units%rowtype;
  payload jsonb;
  replay record;
  archived boolean;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  -- Look up the Property regardless of archived state (archived rows are
  -- not deleted) so both the not-found check and the authorization check
  -- below can run before any idempotency-key replay is honored.
  select * into property_record
  from app.properties
  where organization_id = organization and id = requested_property_id
  for update;

  if not found then
    raise exception 'the requested Property was not found' using errcode = 'P0002';
  end if;

  if not app.actor_can_manage_property(organization, requested_property_id, actor) then
    raise exception 'the actor is not authorized to manage this Property' using errcode = '42501';
  end if;

  -- Idempotency-key replay (PROP-014): resolved only after the current
  -- actor's authorization is confirmed above, so a caller whose membership
  -- or property assignment has since been revoked cannot replay a cached
  -- archive result they are no longer authorized to see.
  payload := jsonb_build_object(
    'propertyId', requested_property_id, 'reason', requested_reason,
    'expectedVersion', requested_expected_version
  );

  select * into replay from app.resolve_rental_inventory_creation_replay(
    organization, actor, 'archive_rental_property', requested_idempotency_key, payload
  );

  if replay.is_replay then
    return (replay.replay_result ->> 'archived')::boolean;
  end if;

  -- Not a replay: a Property already archived by a different (non-matching)
  -- request is not-found for a fresh archive attempt.
  if property_record.archived_at is not null then
    raise exception 'the requested Property was not found' using errcode = 'P0002';
  end if;

  if property_record.version <> requested_expected_version then
    raise exception 'the supplied version is stale' using errcode = '40001';
  end if;

  -- Lock every non-archived Unit of this Property before checking for
  -- blocking leases, so a concurrent create_lease_draft call (which locks
  -- the same Unit row before inserting) cannot create a new lease on one
  -- of these Units between this check and the archive below.
  perform 1 from app.units
  where organization_id = organization
    and property_id = requested_property_id
    and archived_at is null
  for update;

  select count(*) into blocking_lease_count
  from app.leases as lease
  join app.units as unit
    on unit.organization_id = lease.organization_id and unit.id = lease.unit_id
  where unit.organization_id = organization and unit.property_id = requested_property_id
    and lease.archived_at is null;

  -- REQ-036/PROP-016: guard the authoritative occupancy state directly, not
  -- only the presence of a non-archived lease row (see archive_rental_unit).
  select count(*) into occupied_unit_count
  from app.units
  where organization_id = organization
    and property_id = requested_property_id
    and archived_at is null
    and availability_status = 'occupied';

  if blocking_lease_count > 0 or occupied_unit_count > 0 then
    archived := false;
  else
    update app.public_listings
    set status = 'withdrawn', withdrawn_at = transaction_timestamp(),
        version = version + 1, updated_at = transaction_timestamp()
    where organization_id = organization
      and property_id = requested_property_id
      and status = 'published';

    -- History rows are append-only (see archive_rental_unit for the
    -- trigger rationale): close each open interval at `now`, or at the
    -- instant after its own effective_from if it has not started yet, so
    -- no open interval remains once every Unit is archived.
    update app.unit_availability_versions as availability
    set effective_to = case
      when availability.effective_from > clock_timestamp()
        then availability.effective_from + interval '1 microsecond'
      else clock_timestamp()
    end
    from app.units as unit
    where unit.organization_id = organization
      and unit.property_id = requested_property_id
      and availability.organization_id = unit.organization_id
      and availability.unit_id = unit.id
      and availability.effective_to is null;

    for unit_row in
      select * from app.units
      where organization_id = organization
        and property_id = requested_property_id
        and archived_at is null
      for update
    loop
      update app.units
      set archived_at = transaction_timestamp(), archived_by = actor,
          archive_reason = requested_reason, publication_status = 'archived',
          version = version + 1, updated_at = transaction_timestamp()
      where organization_id = organization and id = unit_row.id
      returning version into unit_row.version;

      perform app.record_rental_inventory_event(
        organization, 'unit', unit_row.id, unit_row.version, actor,
        correlation, 'unit.archived', requested_reason, requested_source
      );
    end loop;

    update app.properties
    set archived_at = transaction_timestamp(), archived_by = actor,
        archive_reason = requested_reason, publication_status = 'archived',
        version = version + 1, updated_at = transaction_timestamp()
    where organization_id = organization and id = requested_property_id;

    perform app.record_rental_inventory_event(
      organization, 'property', requested_property_id, property_record.version + 1,
      actor, correlation, 'property.archived', requested_reason, requested_source
    );

    archived := true;
  end if;

  perform app.record_rental_inventory_creation_replay(
    organization, actor, 'archive_rental_property', requested_idempotency_key, payload,
    jsonb_build_object('archived', archived)
  );

  return archived;
end
$$;

CREATE FUNCTION app.archive_rental_unit(requested_unit_id uuid, requested_reason text, requested_expected_version integer, requested_idempotency_key text, requested_correlation_id text, requested_source text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := coalesce(requested_correlation_id, nullif(current_setting('app.correlation_id', true), ''));
  target_property_id uuid;
  unit_record app.units%rowtype;
  active_unit_count integer;
  blocking_lease_count integer;
  payload jsonb;
  replay record;
  archived boolean;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  -- A Unit's property_id is immutable once created (no migration ever
  -- updates it), so this unlocked lookup is safe to use only to determine
  -- which Property to lock first.
  select property_id into target_property_id
  from app.units
  where organization_id = organization and id = requested_unit_id;

  if not found then
    raise exception 'the requested Unit was not found' using errcode = 'P0002';
  end if;

  -- Lock the parent Property before the Unit so this command's lock order
  -- matches archive_rental_property (Property before Unit). Without this,
  -- a concurrent Unit archive and Property archive on the same Property
  -- could lock in opposite orders and deadlock instead of serializing.
  perform 1 from app.properties
  where organization_id = organization and id = target_property_id
  for update;

  -- Look up the Unit regardless of archived state (archived rows are not
  -- deleted) so both the not-found check and the authorization check below
  -- can run before any idempotency-key replay is honored.
  select * into unit_record
  from app.units
  where organization_id = organization and id = requested_unit_id
  for update;

  if not found then
    raise exception 'the requested Unit was not found' using errcode = 'P0002';
  end if;

  if not app.actor_can_manage_property(organization, unit_record.property_id, actor) then
    raise exception 'the actor is not authorized to manage this Unit' using errcode = '42501';
  end if;

  -- Idempotency-key replay (PROP-014): resolved only after the current
  -- actor's authorization is confirmed above, so a caller whose membership
  -- or property assignment has since been revoked cannot replay a cached
  -- archive result they are no longer authorized to see.
  payload := jsonb_build_object(
    'unitId', requested_unit_id, 'reason', requested_reason,
    'expectedVersion', requested_expected_version
  );

  select * into replay from app.resolve_rental_inventory_creation_replay(
    organization, actor, 'archive_rental_unit', requested_idempotency_key, payload
  );

  if replay.is_replay then
    return (replay.replay_result ->> 'archived')::boolean;
  end if;

  -- Not a replay: a Unit already archived by a different (non-matching)
  -- request is not-found for a fresh archive attempt.
  if unit_record.archived_at is not null then
    raise exception 'the requested Unit was not found' using errcode = 'P0002';
  end if;

  if unit_record.version <> requested_expected_version then
    raise exception 'the supplied version is stale' using errcode = '40001';
  end if;

  -- The parent Property is already locked above (before the Unit), which
  -- also serializes concurrent archives of sibling Units on this Property:
  -- whichever transaction locks the Property first proceeds, and the other
  -- re-counts active Units after the first commits.

  select count(*) into active_unit_count
  from app.units
  where organization_id = organization
    and property_id = unit_record.property_id
    and archived_at is null;

  if active_unit_count <= 1 then
    archived := false;
  elsif unit_record.availability_status = 'occupied' then
    -- REQ-036/PROP-016: guard the authoritative occupancy state directly,
    -- not only the presence of a non-archived lease row, since occupancy
    -- can be recorded independently of (or become stale relative to) the
    -- leases table.
    archived := false;
  else
    select count(*) into blocking_lease_count
    from app.leases
    where organization_id = organization and unit_id = requested_unit_id
      and archived_at is null;

    if blocking_lease_count > 0 then
      archived := false;
    else
      update app.public_listings
      set status = 'withdrawn', withdrawn_at = transaction_timestamp(),
          version = version + 1, updated_at = transaction_timestamp()
      where organization_id = organization and unit_id = requested_unit_id and status = 'published';

      -- History rows are append-only (a trigger rejects DELETE and any
      -- UPDATE other than closing effective_to from null), so a
      -- not-yet-started (future-dated) interval cannot be removed; it is
      -- closed at the instant after its own effective_from, which satisfies
      -- the half-open interval constraint (effective_to > effective_from)
      -- while leaving no open interval once the Unit is archived.
      update app.unit_availability_versions
      set effective_to = case
        when effective_from > clock_timestamp() then effective_from + interval '1 microsecond'
        else clock_timestamp()
      end
      where organization_id = organization
        and unit_id = requested_unit_id
        and effective_to is null;

      update app.units
      set archived_at = transaction_timestamp(), archived_by = actor,
          archive_reason = requested_reason, publication_status = 'archived',
          version = version + 1, updated_at = transaction_timestamp()
      where organization_id = organization and id = requested_unit_id;

      perform app.record_rental_inventory_event(
        organization, 'unit', requested_unit_id, unit_record.version + 1, actor,
        correlation, 'unit.archived', requested_reason, requested_source
      );

      archived := true;
    end if;
  end if;

  perform app.record_rental_inventory_creation_replay(
    organization, actor, 'archive_rental_unit', requested_idempotency_key, payload,
    jsonb_build_object('archived', archived)
  );

  return archived;
end
$$;

CREATE FUNCTION app.count_public_listing_images(requested_organization_id uuid, requested_listing_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
  select
    coalesce((
      select jsonb_array_length(listing.snapshot -> 'projection' -> 'imageUrls')
      from app.public_listings as listing
      where listing.organization_id = requested_organization_id
        and listing.id = requested_listing_id
    ), 0)
    + coalesce((
      select count(*)::integer
      from app.public_listing_images as image
      where image.organization_id = requested_organization_id
        and image.public_listing_id = requested_listing_id
        and image.deleted_at is null
    ), 0)
$$;

CREATE TABLE app.leases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    tenant_user_id uuid NOT NULL,
    currency character(3) NOT NULL,
    base_rent_minor bigint NOT NULL,
    starts_on date NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    accepted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_series_id uuid NOT NULL,
    supersedes_lease_id uuid,
    archived_at timestamp with time zone,
    source_type app.lease_source_type NOT NULL,
    application_id uuid,
    external_justification text,
    CONSTRAINT leases_base_rent_minor_check CHECK ((base_rent_minor > 0)),
    CONSTRAINT leases_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT leases_source_is_complete CHECK ((((source_type = 'platform_application'::app.lease_source_type) AND (application_id IS NOT NULL) AND (external_justification IS NULL)) OR ((source_type = 'external'::app.lease_source_type) AND (application_id IS NULL) AND ((length(TRIM(BOTH FROM external_justification)) >= 10) AND (length(TRIM(BOTH FROM external_justification)) <= 1000))))),
    CONSTRAINT leases_version_check CHECK ((version > 0))
);

ALTER TABLE ONLY app.leases FORCE ROW LEVEL SECURITY;

CREATE FUNCTION app.create_lease_draft(requested_unit_id uuid, requested_tenant_user_id uuid, requested_currency character, requested_base_rent_minor bigint, requested_starts_on date, requested_source_type app.lease_source_type, requested_application_id uuid, requested_external_justification text) RETURNS app.leases
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := nullif(current_setting('app.correlation_id', true), '');
  unit_record app.units%rowtype;
  created_lease app.leases%rowtype;
begin
  if organization is null or actor is null or correlation is null or not exists (
    select 1 from app.memberships
    where organization_id = organization
      and user_id = actor
      and role = 'landlord'
      and active
  ) then
    raise exception 'landlord context is required';
  end if;
  if requested_base_rent_minor <= 0 then
    raise exception 'base rent must be positive';
  end if;

  select * into unit_record
  from app.units
  where organization_id = organization and id = requested_unit_id
  for update;

  if not found or unit_record.archived_at is not null then
    return null;
  end if;

  if not exists (
    select 1 from app.memberships
    where organization_id = organization
      and user_id = requested_tenant_user_id
      and role = 'tenant'
      and active
  ) then
    return null;
  end if;
  if exists (
    select 1 from app.leases
    where organization_id = organization and unit_id = requested_unit_id
  ) then
    return null;
  end if;

  if requested_source_type = 'platform_application' then
    perform 1
    from app.tenant_applications
    where organization_id = organization
      and id = requested_application_id
      and tenant_user_id = requested_tenant_user_id
      and status = 'approved'
    for update;
    if not found or exists (
      select 1 from app.leases
      where organization_id = organization
        and application_id = requested_application_id
    ) then
      return null;
    end if;
  elsif requested_source_type <> 'external'
    or length(trim(coalesce(requested_external_justification, ''))) not between 10 and 1000
  then
    return null;
  end if;

  insert into app.leases (
    organization_id, unit_id, tenant_user_id, currency,
    base_rent_minor, starts_on, accepted_at, source_type,
    application_id, external_justification
  ) values (
    organization, requested_unit_id, requested_tenant_user_id,
    requested_currency, requested_base_rent_minor, requested_starts_on, null,
    requested_source_type, requested_application_id,
    case when requested_source_type = 'external'
      then trim(requested_external_justification) else null end
  ) returning * into created_lease;

  insert into app.audit_events (
    organization_id, actor_id, correlation_id, action, entity_type, entity_id
  ) values (
    organization, actor, correlation, 'lease.draft_created', 'lease', created_lease.id
  );

  return created_lease;
end
$$;

CREATE FUNCTION app.create_public_listing(requested_unit_id uuid, requested_title text, requested_summary text, requested_image_urls jsonb, requested_attestation_accepted boolean, requested_idempotency_key text, requested_correlation_id text, requested_source text) RETURNS TABLE(listing_id uuid, listing_version integer, unit_id uuid, unit_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := coalesce(requested_correlation_id, nullif(current_setting('app.correlation_id', true), ''));
  unit_record app.units%rowtype;
  created_listing app.public_listings%rowtype;
  payload jsonb;
  replay record;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  if requested_attestation_accepted is not true then
    raise exception
      'the image-rights and consent attestation must be affirmatively accepted' using errcode = '23514';
  end if;

  select * into unit_record
  from app.units
  where organization_id = organization
    and id = requested_unit_id
  for update;

  if not found then
    raise exception 'the requested Unit was not found' using errcode = 'P0002';
  end if;

  if not app.actor_can_manage_property(organization, unit_record.property_id, actor) then
    raise exception 'only an active listing-manager assignment may create a PublicListing'
      using errcode = '42501';
  end if;

  if unit_record.archived_at is not null then
    raise exception 'an archived Unit cannot receive a PublicListing' using errcode = '23514';
  end if;

  payload := jsonb_build_object(
    'unitId', requested_unit_id, 'title', requested_title,
    'summary', requested_summary, 'imageUrls', requested_image_urls,
    'attestationAccepted', requested_attestation_accepted
  );

  select * into replay from app.resolve_rental_inventory_creation_replay(
    organization, actor, 'create_public_listing', requested_idempotency_key, payload
  );

  if replay.is_replay then
    listing_id := (replay.replay_result ->> 'listingId')::uuid;
    listing_version := (replay.replay_result ->> 'listingVersion')::integer;
    unit_id := (replay.replay_result ->> 'unitId')::uuid;
    unit_version := (replay.replay_result ->> 'unitVersion')::integer;
    return next;
    return;
  end if;

  if exists (
    select 1 from app.public_listings as existing_listing
    where existing_listing.organization_id = organization
      and existing_listing.unit_id = requested_unit_id
  ) then
    raise exception 'a PublicListing already exists for this Unit' using errcode = '23505';
  end if;

  perform app.validate_public_listing_media_payload(
    requested_title, requested_summary, requested_image_urls
  );

  insert into app.public_listings (
    organization_id, property_id, unit_id, status, title, snapshot, attestation_accepted_at
  ) values (
    organization, unit_record.property_id, requested_unit_id, 'draft', requested_title,
    jsonb_build_object('projection', jsonb_build_object(
      'title', requested_title, 'summary', requested_summary, 'imageUrls', requested_image_urls
    )),
    transaction_timestamp()
  ) returning * into created_listing;

  update app.units
  set publication_status = 'published',
      version = version + 1
  where organization_id = organization and id = requested_unit_id
  returning version into unit_version;

  perform app.record_rental_inventory_event(
    organization, 'public_listing', created_listing.id, created_listing.version,
    actor, correlation, 'listing.created', 'PublicListing created and submitted for media review',
    requested_source
  );

  listing_id := created_listing.id;
  listing_version := created_listing.version;
  unit_id := requested_unit_id;

  perform app.record_rental_inventory_creation_replay(
    organization, actor, 'create_public_listing', requested_idempotency_key, payload,
    jsonb_build_object(
      'listingId', listing_id, 'listingVersion', listing_version,
      'unitId', unit_id, 'unitVersion', unit_version
    )
  );

  return next;
end
$$;

CREATE FUNCTION app.create_public_listing_inquiry(requested_identifier text, requested_full_name text, requested_email text, requested_phone text, requested_preferred_at timestamp with time zone, requested_message text, requested_locale text, requested_correlation_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  listing record;
begin
  select projection.id, candidate.organization_id into listing
  from app.get_public_listing(requested_identifier) as projection
  join app.public_listings as candidate on candidate.id = projection.id
  limit 1;

  if not found then
    return false;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(listing.id::text || ':' || lower(requested_email), 0));
  perform set_config('app.organization_id', listing.organization_id::text, true);

  if not exists (
    select 1 from app.public_listing_inquiries as inquiry
    where inquiry.listing_id = listing.id
      and lower(inquiry.email) = lower(requested_email)
      and inquiry.created_at > transaction_timestamp() - interval '1 hour'
  ) then
    insert into app.public_listing_inquiries (
      organization_id, listing_id, full_name, email, phone, preferred_at,
      message, locale, correlation_id
    ) values (
      listing.organization_id, listing.id, requested_full_name,
      requested_email, requested_phone, requested_preferred_at,
      requested_message, requested_locale, requested_correlation_id
    );
  end if;

  return true;
end
$$;

CREATE FUNCTION app.create_rental_property(requested_name text, requested_property_type text, requested_address jsonb, requested_time_zone text, requested_jurisdiction_code text, requested_unit_label text, requested_unit_canonical_label text, requested_unit_type text, requested_unit_bedrooms smallint, requested_unit_bathrooms smallint, requested_unit_area_square_meters integer, requested_unit_floor_label text, requested_unit_furnishing_status text, requested_idempotency_key text, requested_correlation_id text, requested_source text) RETURNS TABLE(property_id uuid, property_version integer, unit_id uuid, unit_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := coalesce(requested_correlation_id, nullif(current_setting('app.correlation_id', true), ''));
  created_property app.properties%rowtype;
  created_unit app.units%rowtype;
  payload jsonb;
  replay record;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  if not app.actor_is_active_landlord(organization, actor) then
    raise exception 'only an active landlord may create a Property' using errcode = '42501';
  end if;

  payload := jsonb_build_object(
    'name', requested_name, 'propertyType', requested_property_type,
    'address', requested_address, 'timeZone', requested_time_zone,
    'jurisdictionCode', requested_jurisdiction_code,
    'unitLabel', requested_unit_label, 'unitType', requested_unit_type,
    'unitBedrooms', requested_unit_bedrooms, 'unitBathrooms', requested_unit_bathrooms,
    'unitAreaSquareMeters', requested_unit_area_square_meters,
    'unitFloorLabel', requested_unit_floor_label,
    'unitFurnishingStatus', requested_unit_furnishing_status
  );

  select * into replay from app.resolve_rental_inventory_creation_replay(
    organization, actor, 'create_rental_property', requested_idempotency_key, payload
  );

  if replay.is_replay then
    property_id := (replay.replay_result ->> 'propertyId')::uuid;
    property_version := (replay.replay_result ->> 'propertyVersion')::integer;
    unit_id := (replay.replay_result ->> 'unitId')::uuid;
    unit_version := (replay.replay_result ->> 'unitVersion')::integer;
    return next;
    return;
  end if;

  insert into app.properties (
    organization_id, name, property_type, address, time_zone, jurisdiction_code,
    verification_status, publication_status, version
  ) values (
    organization, requested_name, requested_property_type, requested_address,
    requested_time_zone, requested_jurisdiction_code, 'not_started', 'draft', 1
  ) returning * into created_property;

  -- Self-assign the creating landlord to their new Property so that
  -- app.set_public_listing_publication's assignment guard is satisfied
  -- without any additional manual step. `set_manager_property_assignment`
  -- re-checks that `actor` is an active landlord in `organization` (already
  -- just verified above) and inserts both the assignment row and its
  -- matching assignment-event row.
  perform app.set_manager_property_assignment(created_property.id, actor, true);

  insert into app.units (
    organization_id, property_id, label, canonical_label, unit_type, bedrooms,
    bathrooms, area_square_meters, floor_label, furnishing_status,
    availability_status, publication_status, version
  ) values (
    organization, created_property.id, requested_unit_label,
    requested_unit_canonical_label, requested_unit_type, requested_unit_bedrooms,
    requested_unit_bathrooms, requested_unit_area_square_meters,
    requested_unit_floor_label, requested_unit_furnishing_status,
    'unavailable', 'draft', 1
  ) returning * into created_unit;

  insert into app.unit_availability_versions (
    organization_id, unit_id, status, reason_code, effective_from, created_by,
    correlation_id, source
  ) values (
    organization, created_unit.id, 'unavailable', 'not_yet_available',
    transaction_timestamp(), actor, correlation, requested_source
  );

  perform app.record_rental_inventory_event(
    organization, 'property', created_property.id, created_property.version,
    actor, correlation, 'property.created', null, requested_source
  );
  perform app.record_rental_inventory_event(
    organization, 'unit', created_unit.id, created_unit.version, actor,
    correlation, 'unit.created', null, requested_source
  );

  property_id := created_property.id;
  property_version := created_property.version;
  unit_id := created_unit.id;
  unit_version := created_unit.version;

  perform app.record_rental_inventory_creation_replay(
    organization, actor, 'create_rental_property', requested_idempotency_key, payload,
    jsonb_build_object(
      'propertyId', property_id, 'propertyVersion', property_version,
      'unitId', unit_id, 'unitVersion', unit_version
    )
  );

  return next;
end
$$;

CREATE FUNCTION app.current_organization_id() RETURNS uuid
    LANGUAGE sql STABLE
    RETURN (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid;

CREATE FUNCTION app.current_party_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
  select nullif(current_setting('app.party_id', true), '')::uuid
$$;

CREATE TABLE app.landlord_onboarding_applications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    applicant_subject text NOT NULL,
    applicant_object_id uuid NOT NULL,
    applicant_name text NOT NULL,
    proposed_organization_name text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    submitted_correlation_id text NOT NULL,
    submitted_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    decided_at timestamp with time zone,
    CONSTRAINT landlord_onboarding_applicatio_proposed_organization_name_check CHECK (((char_length(btrim(proposed_organization_name)) >= 2) AND (char_length(btrim(proposed_organization_name)) <= 160))),
    CONSTRAINT landlord_onboarding_applications_applicant_name_check CHECK (((char_length(btrim(applicant_name)) >= 2) AND (char_length(btrim(applicant_name)) <= 120))),
    CONSTRAINT landlord_onboarding_applications_applicant_subject_check CHECK (((char_length(btrim(applicant_subject)) >= 1) AND (char_length(btrim(applicant_subject)) <= 500))),
    CONSTRAINT landlord_onboarding_applications_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT landlord_onboarding_applications_submitted_correlation_id_check CHECK (((char_length(submitted_correlation_id) >= 1) AND (char_length(submitted_correlation_id) <= 200)))
);

CREATE FUNCTION app.decide_landlord_onboarding_application(requested_application_id uuid, requested_administrator_subject text, requested_administrator_object_id uuid, requested_outcome text, requested_reason text, requested_correlation_id text) RETURNS SETOF app.landlord_onboarding_applications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  application app.landlord_onboarding_applications%rowtype;
  provisioned_organization_id uuid;
  provisioned_user app.users%rowtype;
  provisioned_membership_id uuid;
  decision_timestamp timestamptz := transaction_timestamp();
begin
  if requested_outcome not in ('approved', 'rejected') then
    raise exception 'invalid landlord onboarding decision';
  end if;

  select candidate.* into application
  from app.landlord_onboarding_applications as candidate
  where candidate.id = requested_application_id
  for update;

  if not found or application.status <> 'pending' then
    return;
  end if;

  if requested_outcome = 'approved' then
    insert into app.organizations (name)
    values (application.proposed_organization_name)
    returning id into provisioned_organization_id;

    insert into app.users (external_subject, display_name)
    values (application.applicant_subject, application.applicant_name)
    on conflict (external_subject) do nothing
    returning * into provisioned_user;

    if provisioned_user.id is null then
      select existing.* into provisioned_user
      from app.users as existing
      where existing.external_subject = application.applicant_subject;
    end if;

    insert into app.memberships (
      organization_id, user_id, party_id, role, active, effective_from
    ) values (
      provisioned_organization_id, provisioned_user.id,
      provisioned_user.party_id, 'landlord', true, decision_timestamp
    ) returning id into provisioned_membership_id;
  end if;

  insert into app.landlord_onboarding_decisions (
    application_id, applicant_subject, applicant_object_id, applicant_name,
    administrator_subject, administrator_object_id, outcome, reason,
    correlation_id, organization_id, user_id, membership_id, decided_at
  ) values (
    application.id, application.applicant_subject, application.applicant_object_id,
    application.applicant_name, btrim(requested_administrator_subject),
    requested_administrator_object_id, requested_outcome, btrim(requested_reason),
    requested_correlation_id, provisioned_organization_id, provisioned_user.id,
    provisioned_membership_id, decision_timestamp
  );

  update app.landlord_onboarding_applications
  set status = requested_outcome, decided_at = decision_timestamp
  where id = application.id
  returning * into application;

  return next application;
end
$$;

CREATE FUNCTION app.delete_public_listing_image(requested_listing_id uuid, requested_image_id uuid, requested_correlation_id text, requested_source text) RETURNS TABLE(listing_id uuid, listing_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := coalesce(requested_correlation_id, nullif(current_setting('app.correlation_id', true), ''));
  listing app.public_listings%rowtype;
  delete_count integer;
  updated_version integer;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  select * into listing
  from app.public_listings
  where organization_id = organization and id = requested_listing_id
  for update;

  if not found then
    return;
  end if;

  if not app.actor_can_manage_property(organization, listing.property_id, actor) then
    raise exception 'only an active listing-manager assignment may delete media for this PublicListing'
      using errcode = '42501';
  end if;

  if listing.status not in ('draft', 'withdrawn') then
    raise exception 'only a draft or withdrawn PublicListing may have images removed' using errcode = '23514';
  end if;

  -- Soft-delete only (REQ-038 decision 4): the row and its bytes are
  -- retained for recovery until a separate purge process runs, never
  -- hard-deleted here. Every active-image read path filters
  -- `deleted_at is null`.
  update app.public_listing_images
  set deleted_at = transaction_timestamp()
  where organization_id = organization
    and public_listing_id = requested_listing_id
    and id = requested_image_id
    and deleted_at is null;
  get diagnostics delete_count = row_count;

  if delete_count = 0 then
    return;
  end if;

  update app.public_listings
  set media_review_status = 'pending',
      media_reviewed_at = null,
      media_reviewer_subject = null,
      media_reviewer_object_id = null,
      media_review_notes = null,
      version = version + 1,
      updated_at = transaction_timestamp()
  where id = listing.id
  returning version into updated_version;

  perform app.record_rental_inventory_event(
    organization, 'public_listing', listing.id, updated_version,
    actor, correlation, 'listing.image_deleted',
    'An image was deleted and the listing resubmitted for media review',
    requested_source
  );

  listing_id := listing.id;
  listing_version := updated_version;
  return next;
end
$$;

CREATE FUNCTION app.enforce_rental_inventory_interval_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'UPDATE'
    and old.effective_to is null
    and new.effective_to is not null
    and to_jsonb(new) - 'effective_to' = to_jsonb(old) - 'effective_to' then
    return new;
  end if;
  raise exception 'rental inventory history is immutable';
end
$$;

CREATE FUNCTION app.ensure_user_party() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
begin
  if new.party_id is null then
    new.party_id := new.id;
  end if;

  insert into app.parties (id, preferred_name)
  values (new.party_id, new.display_name)
  on conflict (id) do update
    set preferred_name = excluded.preferred_name,
        updated_at = now(),
        version = app.parties.version + 1;

  return new;
end
$$;

CREATE FUNCTION app.get_public_listing(requested_identifier text) RETURNS TABLE(id uuid, slug text, title text, summary text, city text, district text, bedrooms integer, bathrooms integer, area_square_meters integer, monthly_rent_minor bigint, currency character, available_from date, amenities text[], image_urls text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
  with matched as (
    select listing.*
    from app.public_listings as listing
    where app.runtime_public_listing_is_eligible(listing.id)
      and (
        listing.id::text = requested_identifier
        or lower((listing.snapshot -> 'projection' ->> 'id')) = lower(requested_identifier)
      )
    order by case when listing.id::text = requested_identifier then 0 else 1 end,
      listing.published_at desc,
      listing.id
    limit 1
  )
  select
    matched.id,
    matched.snapshot -> 'projection' ->> 'id' as slug,
    matched.snapshot -> 'projection' ->> 'name' as title,
    matched.snapshot -> 'projection' ->> 'summary' as summary,
    matched.snapshot -> 'projection' ->> 'city' as city,
    matched.snapshot -> 'projection' ->> 'district' as district,
    ((matched.snapshot -> 'projection' ->> 'bedrooms'))::integer as bedrooms,
    ((matched.snapshot -> 'projection' ->> 'bathrooms'))::integer as bathrooms,
    case
      when matched.snapshot -> 'projection' ? 'areaSquareMeters'
        then ((matched.snapshot -> 'projection' ->> 'areaSquareMeters'))::integer
      else null
    end as area_square_meters,
    ((matched.snapshot -> 'projection' ->> 'monthlyRentMinor'))::bigint as monthly_rent_minor,
    (matched.snapshot -> 'projection' ->> 'currency')::char(3) as currency,
    ((matched.snapshot -> 'projection' ->> 'availableFrom'))::date as available_from,
    coalesce(array(select jsonb_array_elements_text(matched.snapshot -> 'projection' -> 'amenities')), array[]::text[]) as amenities,
    coalesce(array(select jsonb_array_elements_text(matched.snapshot -> 'projection' -> 'imageUrls')), array[]::text[]) as image_urls
  from matched
$$;

