CREATE FUNCTION app.list_public_listing_images_for_actor(requested_listing_id uuid) RETURNS TABLE(image_id uuid, room text, media_type text, size_bytes integer, image_position integer, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  listing app.public_listings%rowtype;
begin
  if organization is null or actor is null then
    raise exception 'trusted request context is required';
  end if;

  select * into listing
  from app.public_listings
  where organization_id = organization and id = requested_listing_id;

  if not found then
    return;
  end if;

  if not app.actor_can_manage_property(organization, listing.property_id, actor) then
    raise exception 'only an active listing-manager assignment may view media for this PublicListing'
      using errcode = '42501';
  end if;

  return query
  select image.id, image.room, image.media_type, image.size_bytes, image.position as image_position, image.created_at
  from app.public_listing_images as image
  where image.organization_id = organization and image.public_listing_id = requested_listing_id
    and image.deleted_at is null
  order by image.position, image.id;
end
$$;

CREATE FUNCTION app.list_public_listings_for_actor() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  result jsonb;
begin
  if organization is null or actor is null then
    raise exception 'trusted request context is required';
  end if;

  select coalesce(jsonb_agg(listing_row order by listing_row ->> 'title'), '[]'::jsonb)
  into result
  from (
    select jsonb_build_object(
      'id', l.id,
      'unitId', l.unit_id,
      'title', coalesce(l.title, p.name || ' — ' || u.label),
      'status', l.status,
      'mediaReviewStatus', l.media_review_status,
      'mediaReviewNotes', l.media_review_notes,
      'summary', l.snapshot -> 'projection' ->> 'summary',
      'imageUrls', coalesce(l.snapshot -> 'projection' -> 'imageUrls', '[]'::jsonb),
      'version', l.version,
      'note', concat_ws(', ', p.address ->> 'commune', p.address ->> 'city')
    ) as listing_row
    from app.public_listings l
    join app.properties p
      on p.organization_id = l.organization_id and p.id = l.property_id
    join app.units u
      on u.organization_id = l.organization_id and u.id = l.unit_id
    where l.organization_id = organization
      and (
        exists (
          select 1
          from app.manager_property_assignment_events as event
          join app.memberships as membership
            on membership.organization_id = event.organization_id
           and membership.user_id = event.manager_user_id
          join app.manager_property_assignments as assignment
            on assignment.organization_id = event.organization_id
           and assignment.property_id = event.property_id
           and assignment.manager_user_id = event.manager_user_id
           and assignment.assigned_at = event.occurred_at
           and assignment.revoked_at is null
          where event.organization_id = organization
            and event.property_id = l.property_id
            and event.manager_user_id = actor
            and event.action = 'assigned'
            and membership.role in ('landlord', 'manager')
            and membership.active
            and membership.effective_from <= transaction_timestamp()
            and (membership.effective_to is null or transaction_timestamp() < membership.effective_to)
          order by event.occurred_at desc, event.id desc
          limit 1
        )
        or (
          -- A landlord may create/edit a PublicListing on a property with no
          -- manager_property_assignments row at all (actor_can_manage_property
          -- authorizes an active landlord unconditionally). Without this
          -- fallback such a listing would never appear in the landlord's own
          -- feed. This does not affect issue #114's scoping: as soon as any
          -- manager (including the landlord acting as a self-assigned
          -- manager) is actively assigned to the property, only that
          -- assignment (via the exists clause above) determines visibility.
          app.actor_is_active_landlord(organization, actor)
          and not exists (
            select 1
            from app.manager_property_assignments as assignment
            where assignment.organization_id = organization
              and assignment.property_id = l.property_id
              and assignment.revoked_at is null
          )
        )
      )
  ) listings;

  return result;
end
$$;

CREATE FUNCTION app.list_public_listings_page(requested_city text, requested_district text, requested_bedrooms integer, requested_max_rent_minor bigint, requested_sort text, requested_cursor text, requested_limit integer) RETURNS TABLE(items jsonb, total_count bigint, next_cursor text, cursor_valid boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
begin
  if requested_sort not in ('created_at_desc', 'name_asc', 'name_desc') then
    raise exception 'unsupported public listing sort';
  end if;
  if requested_limit is null or requested_limit < 1 or requested_limit > 100 then
    raise exception 'public listing limit must be between 1 and 100';
  end if;

  return query
  with filtered as materialized (
    select
      listing.id,
      listing.created_at,
      listing.snapshot -> 'projection' ->> 'id' as slug,
      listing.snapshot -> 'projection' ->> 'name' as title,
      listing.snapshot -> 'projection' ->> 'summary' as summary,
      listing.snapshot -> 'projection' ->> 'city' as city,
      listing.snapshot -> 'projection' ->> 'district' as district,
      ((listing.snapshot -> 'projection' ->> 'bedrooms'))::integer as bedrooms,
      ((listing.snapshot -> 'projection' ->> 'bathrooms'))::integer as bathrooms,
      case
        when listing.snapshot -> 'projection' ? 'areaSquareMeters'
          then ((listing.snapshot -> 'projection' ->> 'areaSquareMeters'))::integer
        else null
      end as area_square_meters,
      ((listing.snapshot -> 'projection' ->> 'monthlyRentMinor'))::bigint as monthly_rent_minor,
      (listing.snapshot -> 'projection' ->> 'currency')::char(3) as currency,
      ((listing.snapshot -> 'projection' ->> 'availableFrom'))::date as available_from,
      coalesce(array(select jsonb_array_elements_text(listing.snapshot -> 'projection' -> 'amenities')), array[]::text[]) as amenities,
      coalesce(array(select jsonb_array_elements_text(listing.snapshot -> 'projection' -> 'imageUrls')), array[]::text[]) as image_urls
    from app.public_listings as listing
    where app.runtime_public_listing_is_eligible(listing.id)
      and (requested_city is null or lower(listing.snapshot -> 'projection' ->> 'city') = lower(requested_city))
      and (requested_district is null or (listing.snapshot -> 'projection' ->> 'district') ilike '%' || requested_district || '%')
      and (requested_bedrooms is null or ((listing.snapshot -> 'projection' ->> 'bedrooms'))::integer >= requested_bedrooms)
      and (requested_max_rent_minor is null or ((listing.snapshot -> 'projection' ->> 'monthlyRentMinor'))::bigint <= requested_max_rent_minor)
  ), cursor_row as (
    select candidate.created_at, candidate.id, candidate.slug, candidate.title
    from filtered as candidate
    where candidate.slug = requested_cursor
  ), eligible as (
    select candidate.*
    from filtered as candidate
    where requested_cursor is null
      or (
        requested_sort = 'created_at_desc'
        and (
          candidate.created_at < (select cursor_row.created_at from cursor_row)
          or (candidate.created_at = (select cursor_row.created_at from cursor_row) and candidate.id > (select cursor_row.id from cursor_row))
        )
      )
      or (
        requested_sort = 'name_asc'
        and (
          candidate.title > (select cursor_row.title from cursor_row)
          or (candidate.title = (select cursor_row.title from cursor_row) and candidate.id > (select cursor_row.id from cursor_row))
        )
      )
      or (
        requested_sort = 'name_desc'
        and (
          candidate.title < (select cursor_row.title from cursor_row)
          or (candidate.title = (select cursor_row.title from cursor_row) and candidate.id > (select cursor_row.id from cursor_row))
        )
      )
  ), ordered as (
    select candidate.*,
      row_number() over (
        order by
          case when requested_sort = 'created_at_desc' then candidate.created_at end desc,
          case when requested_sort = 'name_asc' then candidate.title end asc,
          case when requested_sort = 'name_desc' then candidate.title end desc,
          candidate.id asc
      ) as ordinal
    from eligible as candidate
    order by
      case when requested_sort = 'created_at_desc' then candidate.created_at end desc,
      case when requested_sort = 'name_asc' then candidate.title end asc,
      case when requested_sort = 'name_desc' then candidate.title end desc,
      candidate.id asc
    limit requested_limit + 1
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'slug', page.slug,
          'title', page.title,
          'summary', page.summary,
          'city', page.city,
          'district', page.district,
          'bedrooms', page.bedrooms,
          'bathrooms', page.bathrooms,
          'area_square_meters', page.area_square_meters,
          'monthly_rent_minor', page.monthly_rent_minor::text,
          'currency', page.currency,
          'available_from', page.available_from,
          'amenities', page.amenities,
          'image_urls', page.image_urls
        ) order by page.ordinal
      ) filter (where page.ordinal <= requested_limit),
      '[]'::jsonb
    ),
    (select count(*) from filtered),
    case when count(*) > requested_limit then
      (array_agg(page.slug order by page.ordinal) filter (where page.ordinal <= requested_limit))[requested_limit]
    else null end,
    requested_cursor is null or exists (select 1 from cursor_row)
  from ordered as page;
end
$$;

--
-- Name: list_public_listings_pending_media_review(); Type: FUNCTION; Schema: app; Owner: keyforta_media_review_admin
--

CREATE FUNCTION app.list_public_listings_pending_media_review() RETURNS TABLE(listing_id uuid, organization_id uuid, organization_name text, unit_id uuid, property_name text, unit_label text, title text, summary text, image_urls jsonb, uploaded_images jsonb, submitted_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
    select l.id, l.organization_id, o.name, l.unit_id, p.name, u.label,
      l.title, l.snapshot -> 'projection' ->> 'summary',
      coalesce(l.snapshot -> 'projection' -> 'imageUrls', '[]'::jsonb),
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'imageId', img.id,
              'room', img.room,
              'mediaType', img.media_type,
              'position', img.position
            )
            order by img.position, img.id
          )
          from app.public_listing_images as img
          where img.public_listing_id = l.id
            and img.deleted_at is null
        ),
        '[]'::jsonb
      ),
      l.created_at
    from app.public_listings l
    join app.organizations o on o.id = l.organization_id
    join app.properties p on p.organization_id = l.organization_id and p.id = l.property_id
    join app.units u on u.organization_id = l.organization_id and u.id = l.unit_id
    where l.status in ('draft', 'withdrawn') and l.media_review_status = 'pending'
    order by l.created_at, l.id;
$$;

ALTER FUNCTION app.list_public_listings_pending_media_review() OWNER TO keyforta_media_review_admin;

CREATE FUNCTION app.list_rental_properties_for_actor() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  is_landlord boolean;
  result jsonb;
begin
  if organization is null or actor is null then
    raise exception 'trusted request context is required';
  end if;

  is_landlord := app.actor_is_active_landlord(organization, actor);

  select coalesce(jsonb_agg(property_row order by property_row ->> 'name'), '[]'::jsonb)
  into result
  from (
    select jsonb_build_object(
      'id', p.id,
      'name', p.name,
      'propertyType', p.property_type,
      'address', p.address,
      'timeZone', p.time_zone,
      'jurisdictionCode', p.jurisdiction_code,
      'verificationStatus', p.verification_status,
      'publicationStatus', p.publication_status,
      'version', p.version,
      'archivedAt', p.archived_at,
      'units', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'id', u.id,
          'label', u.label,
          'unitType', u.unit_type,
          'bedrooms', u.bedrooms,
          'bathrooms', u.bathrooms,
          'areaSquareMeters', u.area_square_meters,
          'floorLabel', u.floor_label,
          'furnishingStatus', u.furnishing_status,
          'availabilityStatus', u.availability_status,
          'publicationStatus', u.publication_status,
          'version', u.version,
          'archivedAt', u.archived_at
        ) order by u.label), '[]'::jsonb)
        from app.units u
        where u.property_id = p.id and u.organization_id = organization
          and u.archived_at is null
      )
    ) as property_row
    from app.properties p
    where p.organization_id = organization
      and p.archived_at is null
      and (
        is_landlord
        or exists (
          select 1
          from app.manager_property_assignments a
          join app.memberships m
            on m.organization_id = a.organization_id
            and m.user_id = a.manager_user_id
          where a.organization_id = organization
            and a.property_id = p.id
            and a.manager_user_id = actor
            and a.revoked_at is null
            and m.role in ('landlord', 'manager')
            and m.active
            and m.effective_from <= transaction_timestamp()
            and (m.effective_to is null or transaction_timestamp() < m.effective_to)
        )
      )
  ) properties_with_units;

  return result;
end
$$;

CREATE FUNCTION app.post_payment(requested_lease_id uuid, requested_amount_minor bigint, requested_currency character, requested_idempotency_key text, requested_provider_reference text) RETURNS TABLE(payment_id uuid, lease_id uuid, amount_minor bigint, currency character, correlation_id text, receipt_id uuid, receipt_number text)
    LANGUAGE plpgsql
    SET search_path TO 'app', 'pg_temp'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := nullif(current_setting('app.correlation_id', true), '');
  existing_payment app.payments%rowtype;
  created_payment app.payments%rowtype;
  created_receipt app.receipts%rowtype;
  sequence_number bigint;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted audit context is required';
  end if;
  if requested_amount_minor <= 0 then
    raise exception 'payment amount must be positive';
  end if;
  if not exists (
    select 1 from app.memberships
    where organization_id = organization
      and user_id = actor
      and active
      and role in ('landlord', 'manager')
  ) then
    raise exception 'actor cannot post payments';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(organization::text || ':' || requested_provider_reference, 0));
  select * into existing_payment
  from app.payments
  where organization_id = organization
    and (
      idempotency_key = requested_idempotency_key
      or provider_reference = requested_provider_reference
    );

  if found then
    if existing_payment.lease_id <> requested_lease_id
      or existing_payment.amount_minor <> requested_amount_minor
      or existing_payment.currency <> requested_currency then
      raise exception 'idempotency conflict';
    end if;
    select receipts.* into created_receipt
    from app.receipts as receipts
    where receipts.payment_id = existing_payment.id;
    return query select existing_payment.id, existing_payment.lease_id,
      existing_payment.amount_minor, existing_payment.currency,
      existing_payment.correlation_id, created_receipt.id, created_receipt.receipt_number;
    return;
  end if;

  insert into app.payments (
    organization_id, lease_id, amount_minor, currency, status,
    idempotency_key, provider_reference, actor_id, correlation_id
  ) values (
    organization, requested_lease_id, requested_amount_minor, requested_currency,
    'posted', requested_idempotency_key, requested_provider_reference, actor, correlation
  ) returning * into created_payment;

  insert into app.receipt_counters (organization_id, next_number)
  values (organization, 2)
  on conflict (organization_id) do update
    set next_number = app.receipt_counters.next_number + 1
  returning next_number - 1 into sequence_number;

  insert into app.receipts (organization_id, payment_id, receipt_number)
  values (
    organization,
    created_payment.id,
    'RCT-' || extract(year from now())::integer || '-' || lpad(sequence_number::text, 6, '0')
  ) returning * into created_receipt;

  insert into app.ledger_entries (
    organization_id, payment_id, account_code, amount_minor, currency
  ) values
    (organization, created_payment.id, 'CASH_CLEARING', requested_amount_minor, requested_currency),
    (organization, created_payment.id, 'TENANT_UNAPPLIED', -requested_amount_minor, requested_currency);

  insert into app.audit_events (
    organization_id, actor_id, correlation_id, action, entity_type, entity_id
  ) values (organization, actor, correlation, 'payment.posted', 'payment', created_payment.id);

  return query select created_payment.id, created_payment.lease_id,
    created_payment.amount_minor, created_payment.currency,
    created_payment.correlation_id, created_receipt.id, created_receipt.receipt_number;
end
$$;

CREATE FUNCTION app.record_rental_inventory_creation_replay(requested_organization_id uuid, requested_actor_id uuid, requested_operation text, requested_idempotency_key text, requested_payload jsonb, requested_result jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
  update app.rental_inventory_creation_replays
  set result = requested_result
  where organization_id = requested_organization_id
    and actor_id = requested_actor_id
    and operation = requested_operation
    and idempotency_key = requested_idempotency_key
$$;

