CREATE FUNCTION app.resolve_active_jurisdiction_policy(requested_policy_key text, requested_jurisdiction_code text, requested_at timestamp with time zone DEFAULT transaction_timestamp()) RETURNS TABLE(policy_key text, version integer, rule_payload jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
  select policy.policy_key, policy.version, policy.rule_payload
  from app.jurisdiction_policy_activations as activation
  join app.jurisdiction_policy_versions as policy
    on policy.id = activation.policy_version_id
  join app.policy_approval_evidence as owner_evidence
    on owner_evidence.id = activation.owner_evidence_id
   and owner_evidence.policy_version_id = policy.id
   and owner_evidence.approval_role = 'policy_owner'
  left join app.policy_approval_evidence as counsel_evidence
    on counsel_evidence.id = activation.counsel_evidence_id
   and counsel_evidence.policy_version_id = policy.id
   and counsel_evidence.approval_role = 'qualified_counsel'
  where activation.policy_key = requested_policy_key
    and activation.jurisdiction_code = requested_jurisdiction_code
    and activation.effective_from <= requested_at
    and (activation.effective_to is null or requested_at < activation.effective_to)
    and not exists (
      select 1 from app.policy_approval_revocations as revocation
      where revocation.approval_evidence_id = owner_evidence.id
    )
    and (
      not policy.requires_counsel_approval
      or (
        counsel_evidence.id is not null
        and not exists (
          select 1 from app.policy_approval_revocations as revocation
          where revocation.approval_evidence_id = counsel_evidence.id
        )
      )
    )
$$;

CREATE FUNCTION app.resolve_actor(subject text, requested_organization_id uuid) RETURNS TABLE(actor_id uuid, organization_id uuid, role app.organization_role)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
declare
  resolved_actor_id uuid;
  resolved_party_id uuid;
  resolved_organization_id uuid;
  resolved_role app.organization_role;
begin
  perform set_config('app.organization_id', '', true);
  perform set_config('app.actor_id', '', true);
  perform set_config('app.party_id', '', true);

  select users.id, users.party_id, memberships.organization_id, memberships.role
  into resolved_actor_id, resolved_party_id, resolved_organization_id, resolved_role
  from app.users
  join app.memberships on memberships.user_id = users.id
  where users.external_subject = subject
    and memberships.organization_id = requested_organization_id
    and memberships.active
    and memberships.effective_from <= transaction_timestamp()
    and (
      memberships.effective_to is null
      or transaction_timestamp() < memberships.effective_to
    );

  if found then
    perform set_config('app.organization_id', resolved_organization_id::text, true);
    perform set_config('app.actor_id', resolved_actor_id::text, true);
    perform set_config('app.party_id', resolved_party_id::text, true);
    actor_id := resolved_actor_id;
    organization_id := resolved_organization_id;
    role := resolved_role;
    return next;
  end if;
end
$$;

CREATE FUNCTION app.resolve_actor_memberships(subject text) RETURNS TABLE(organization_id uuid, role app.organization_role, actor_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
begin
  return query
    select memberships.organization_id, memberships.role, users.id as actor_id
    from app.users
    join app.memberships on memberships.user_id = users.id
    where users.external_subject = subject
      and memberships.active;
end
$$;

CREATE FUNCTION app.resolve_platform_actor(subject text) RETURNS TABLE(actor_id uuid, party_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
declare
  resolved_actor_id uuid;
  resolved_party_id uuid;
begin
  perform set_config('app.organization_id', '', true);
  perform set_config('app.actor_id', '', true);
  perform set_config('app.party_id', '', true);

  select users.id, users.party_id
  into resolved_actor_id, resolved_party_id
  from app.users
  where users.external_subject = subject;

  if found then
    perform set_config('app.actor_id', resolved_actor_id::text, true);
    perform set_config('app.party_id', resolved_party_id::text, true);
    actor_id := resolved_actor_id;
    party_id := resolved_party_id;
    return next;
  end if;
end
$$;

CREATE FUNCTION app.resolve_rental_inventory_creation_replay(requested_organization_id uuid, requested_actor_id uuid, requested_operation text, requested_idempotency_key text, requested_payload jsonb, OUT replay_result jsonb, OUT is_replay boolean) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  existing app.rental_inventory_creation_replays%rowtype;
  payload_hash text := encode(public.digest(requested_payload::text, 'sha256'), 'hex');
begin
  insert into app.rental_inventory_creation_replays (
    organization_id, actor_id, operation, idempotency_key, payload_hash, result
  ) values (
    requested_organization_id, requested_actor_id, requested_operation,
    requested_idempotency_key, payload_hash, null
  )
  on conflict (organization_id, actor_id, operation, idempotency_key) do nothing;

  select * into existing
  from app.rental_inventory_creation_replays
  where organization_id = requested_organization_id
    and actor_id = requested_actor_id
    and operation = requested_operation
    and idempotency_key = requested_idempotency_key
  for update;

  if existing.payload_hash <> payload_hash then
    raise exception 'the idempotency key was already used with a different payload'
      using errcode = '23505';
  end if;

  if existing.result is null then
    replay_result := null;
    is_replay := false;
    return;
  end if;

  replay_result := existing.result;
  is_replay := true;
end
$$;

CREATE FUNCTION app.reverse_payment(requested_payment_id uuid, requested_reason text) RETURNS TABLE(payment_id uuid, lease_id uuid, amount_minor bigint, currency character, correlation_id text, reverses_payment_id uuid, reason text)
    LANGUAGE plpgsql
    SET search_path TO 'app', 'pg_temp'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := nullif(current_setting('app.correlation_id', true), '');
  original app.payments%rowtype;
  reversal app.payments%rowtype;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted audit context is required';
  end if;
  if length(trim(requested_reason)) < 3 then
    raise exception 'reversal reason is required';
  end if;

  select * into original
  from app.payments
  where organization_id = organization
    and id = requested_payment_id
    and status = 'posted';
  if not found then return; end if;

  select payment.* into reversal
  from app.payments as payment
  where payment.organization_id = organization
    and payment.reverses_payment_id = original.id;
  if found then
    return query select reversal.id, reversal.lease_id,
      reversal.amount_minor, reversal.currency, reversal.correlation_id,
      reversal.reverses_payment_id, reversal.reason;
    return;
  end if;

  insert into app.payments (
    organization_id, lease_id, amount_minor, currency, status,
    idempotency_key, provider_reference, reverses_payment_id, reason,
    actor_id, correlation_id
  ) values (
    organization, original.lease_id, -original.amount_minor,
    original.currency, 'reversal', 'reversal:' || original.id,
    'reversal:' || original.id, original.id, trim(requested_reason),
    actor, correlation
  ) returning * into reversal;

  insert into app.ledger_entries (
    organization_id, payment_id, account_code, amount_minor, currency
  ) values
    (organization, reversal.id, 'CASH_CLEARING', reversal.amount_minor, reversal.currency),
    (organization, reversal.id, 'TENANT_UNAPPLIED', -reversal.amount_minor, reversal.currency);

  insert into app.audit_events (
    organization_id, actor_id, correlation_id, action, entity_type, entity_id
  ) values (
    organization, actor, correlation, 'payment.reversed', 'payment', reversal.id
  );

  return query select reversal.id, reversal.lease_id,
    reversal.amount_minor, reversal.currency, reversal.correlation_id,
    reversal.reverses_payment_id, reversal.reason;
end
$$;

--
-- Name: review_public_listing_media(uuid, text, text, uuid, text, text, text); Type: FUNCTION; Schema: app; Owner: keyforta_media_review_admin
--

CREATE FUNCTION app.review_public_listing_media(requested_listing_id uuid, requested_decision text, requested_reviewer_subject text, requested_reviewer_object_id uuid, requested_notes text, requested_correlation_id text, requested_source text) RETURNS TABLE(listing_id uuid, media_review_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  listing app.public_listings%rowtype;
  updated_version integer;
  assignment_manager_id uuid;
  assignment_event_id uuid;
  property_record app.properties%rowtype;
  unit_record app.units%rowtype;
  current_pricing record;
  current_availability record;
  listing_snapshot jsonb;
  total_image_count integer;
begin
  if requested_decision not in ('approved', 'rejected') then
    raise exception 'invalid media review decision';
  end if;
  if requested_decision = 'rejected'
    and (requested_notes is null or char_length(btrim(requested_notes)) < 1) then
    raise exception 'rejecting a listing requires reviewer notes' using errcode = '23514';
  end if;

  select * into listing
  from app.public_listings
  where id = requested_listing_id
  for update;

  if not found or listing.status not in ('draft', 'withdrawn') or listing.media_review_status <> 'pending' then
    return;
  end if;

  update app.public_listings
  set media_review_status = requested_decision,
      media_reviewed_at = transaction_timestamp(),
      media_reviewer_subject = requested_reviewer_subject,
      media_reviewer_object_id = requested_reviewer_object_id,
      media_review_notes = requested_notes,
      version = version + 1,
      updated_at = transaction_timestamp()
  where id = listing.id
  returning id, version into listing_id, updated_version;

  insert into app.public_listing_media_review_events (
    organization_id, listing_id, listing_version, reviewer_subject, reviewer_object_id,
    decision, notes, correlation_id, source
  ) values (
    listing.organization_id, listing.id, updated_version, requested_reviewer_subject,
    requested_reviewer_object_id, requested_decision, requested_notes, requested_correlation_id,
    requested_source
  );

  if requested_decision = 'approved' then
    select assignment.manager_user_id into assignment_manager_id
    from app.manager_property_assignments as assignment
    join app.memberships as membership
      on membership.organization_id = assignment.organization_id
     and membership.user_id = assignment.manager_user_id
    where assignment.organization_id = listing.organization_id
      and assignment.property_id = listing.property_id
      and assignment.revoked_at is null
      and membership.role in ('landlord', 'manager')
      and membership.active
      and membership.effective_from <= transaction_timestamp()
      and (
        membership.effective_to is null
        or transaction_timestamp() < membership.effective_to
      )
    limit 1;

    if assignment_manager_id is not null then
      select event.id into assignment_event_id
      from app.manager_property_assignment_events as event
      where event.organization_id = listing.organization_id
        and event.property_id = listing.property_id
        and event.manager_user_id = assignment_manager_id
        and event.action = 'assigned'
      order by event.occurred_at desc, event.id desc
      limit 1;
    end if;

    if listing.status = 'draft' and assignment_manager_id is not null and assignment_event_id is not null then
      select * into property_record
      from app.properties
      where organization_id = listing.organization_id
        and id = listing.property_id;
      select * into unit_record
      from app.units
      where organization_id = listing.organization_id
        and id = listing.unit_id
        and property_id = listing.property_id;

      if found
        and property_record.archived_at is null
        and property_record.verification_status not in ('rejected', 'expired', 'suspended')
        and property_record.publication_status in ('draft', 'pending_review', 'paused')
        and unit_record.archived_at is null
        and unit_record.publication_status = 'published' then

        select pricing.id, pricing.amount_minor, pricing.currency into current_pricing
        from app.unit_pricing_versions as pricing
        where pricing.organization_id = listing.organization_id
          and pricing.unit_id = listing.unit_id
          and pricing.effective_from <= transaction_timestamp()
          and (pricing.effective_to is null or transaction_timestamp() < pricing.effective_to)
        order by pricing.effective_from desc, pricing.id desc
        limit 1;

        select availability.id, availability.status, availability.effective_from
          into current_availability
        from app.unit_availability_versions as availability
        where availability.organization_id = listing.organization_id
          and availability.unit_id = listing.unit_id
          and availability.effective_from <= transaction_timestamp()
          and (availability.effective_to is null or transaction_timestamp() < availability.effective_to)
        order by availability.effective_from desc, availability.id desc
        limit 1;

        select app.count_public_listing_images(listing.organization_id, listing.id) into total_image_count;

        if current_pricing.id is not null
          and current_availability.id is not null
          and current_availability.status = 'available'
          and total_image_count >= 1 then

          listing_snapshot := jsonb_build_object(
            'propertyId', listing.property_id,
            'propertyVersion', property_record.version,
            'unitId', listing.unit_id,
            'unitVersion', unit_record.version,
            'pricingVersionId', current_pricing.id,
            'availabilityVersionId', current_availability.id,
            'projection', jsonb_build_object(
              'id', listing.id::text,
              'name', coalesce(listing.title, property_record.name || ' — ' || unit_record.label),
              'summary', coalesce(listing.snapshot -> 'projection' ->> 'summary', property_record.name || ' listing'),
              'city', property_record.address ->> 'city',
              'district', property_record.address ->> 'quartier',
              'bedrooms', unit_record.bedrooms,
              'bathrooms', unit_record.bathrooms,
              'monthlyRentMinor', current_pricing.amount_minor::text,
              'currency', current_pricing.currency,
              'availableFrom', (current_availability.effective_from at time zone 'UTC')::date,
              'amenities', coalesce(listing.snapshot -> 'projection' -> 'amenities', '[]'::jsonb),
              'imageUrls', coalesce(listing.snapshot -> 'projection' -> 'imageUrls', '[]'::jsonb),
              'areaSquareMeters', unit_record.area_square_meters
            )
          );

          update app.public_listings
          set status = 'published',
              snapshot = listing_snapshot,
              version = version + 1,
              published_at = transaction_timestamp(),
              withdrawn_at = null,
              updated_at = transaction_timestamp()
          where id = listing.id
          returning version into updated_version;

          insert into app.public_listing_publication_events (
            organization_id, listing_id, property_id, unit_id, actor_id,
            manager_assignment_event_id, manager_assignment_action, listing_version,
            correlation_id, action, source, occurred_at
          ) values (
            listing.organization_id, listing.id, listing.property_id, listing.unit_id,
            assignment_manager_id, assignment_event_id, 'assigned', updated_version,
            requested_correlation_id, 'published', requested_source, transaction_timestamp()
          );
        end if;
      end if;
    end if;
  end if;

  media_review_status := requested_decision;
  return next;
end
$$;

ALTER FUNCTION app.review_public_listing_media(requested_listing_id uuid, requested_decision text, requested_reviewer_subject text, requested_reviewer_object_id uuid, requested_notes text, requested_correlation_id text, requested_source text) OWNER TO keyforta_media_review_admin;

CREATE FUNCTION app.runtime_public_listing_is_eligible(requested_listing_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
  select exists (
    select 1
    from app.public_listings as listing
    join app.units as unit
      on unit.id = listing.unit_id
     and unit.organization_id = listing.organization_id
    join app.properties as property
      on property.id = listing.property_id
     and property.organization_id = listing.organization_id
    join lateral (
      select pricing.id, pricing.amount_minor
      from app.unit_pricing_versions as pricing
      where pricing.organization_id = listing.organization_id
        and pricing.unit_id = listing.unit_id
        and pricing.effective_from <= transaction_timestamp()
        and (
          pricing.effective_to is null
          or transaction_timestamp() < pricing.effective_to
        )
      order by pricing.effective_from desc, pricing.id desc
      limit 1
    ) as current_pricing on true
    join lateral (
      select availability.id, availability.status
      from app.unit_availability_versions as availability
      where availability.organization_id = listing.organization_id
        and availability.unit_id = listing.unit_id
        and availability.effective_from <= transaction_timestamp()
        and (
          availability.effective_to is null
          or transaction_timestamp() < availability.effective_to
        )
      order by availability.effective_from desc, availability.id desc
      limit 1
    ) as current_availability on true
    where listing.id = requested_listing_id
      and listing.status = 'published'
      and listing.snapshot is not null
      and listing.published_at is not null
      and listing.withdrawn_at is null
      and property.archived_at is null
      and property.verification_status not in ('rejected', 'expired', 'suspended')
      and property.publication_status in ('draft', 'pending_review')
      and unit.archived_at is null
      and unit.publication_status = 'published'
      and current_availability.status = 'available'
      and current_pricing.amount_minor > 0
  )
$$;

