CREATE FUNCTION app.set_manager_property_assignment(requested_property_id uuid, requested_manager_user_id uuid, requested_assigned boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := nullif(current_setting('app.correlation_id', true), '');
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  if not exists (
    select 1
    from app.memberships as membership
    where membership.organization_id = organization
      and membership.user_id = actor
      and membership.role = 'landlord'
      and membership.active
      and membership.effective_from <= transaction_timestamp()
      and (
        membership.effective_to is null
        or transaction_timestamp() < membership.effective_to
      )
  ) then
    return false;
  end if;

  if not exists (
    select 1
    from app.properties as property
    join app.memberships as membership
      on membership.organization_id = property.organization_id
    where property.id = requested_property_id
      and property.organization_id = organization
      and property.archived_at is null
      and membership.user_id = requested_manager_user_id
      and membership.role in ('landlord', 'manager')
      and membership.active
      and membership.effective_from <= transaction_timestamp()
      and (
        membership.effective_to is null
        or transaction_timestamp() < membership.effective_to
      )
  ) then
    return false;
  end if;

  if requested_assigned then
    if exists (
      select 1 from app.manager_property_assignments
      where organization_id = organization
        and property_id = requested_property_id
        and manager_user_id = requested_manager_user_id
        and revoked_at is null
    ) then
      return false;
    end if;

    insert into app.manager_property_assignment_events (
      organization_id, property_id, manager_user_id, actor_id,
      correlation_id, action
    )
    select organization, requested_property_id, manager_user_id, actor,
      correlation, 'revoked'
    from app.manager_property_assignments
    where organization_id = organization
      and property_id = requested_property_id
      and revoked_at is null;

    update app.manager_property_assignments
    set revoked_at = transaction_timestamp()
    where organization_id = organization
      and property_id = requested_property_id
      and revoked_at is null;

    insert into app.manager_property_assignments (
      organization_id, property_id, manager_user_id, assigned_by_user_id
    ) values (
      organization, requested_property_id, requested_manager_user_id, actor
    )
    on conflict (organization_id, property_id, manager_user_id)
    do update set assigned_by_user_id = excluded.assigned_by_user_id,
                  assigned_at = transaction_timestamp(), revoked_at = null;

    insert into app.manager_property_assignment_events (
      organization_id, property_id, manager_user_id, actor_id,
      correlation_id, action
    ) values (
      organization, requested_property_id, requested_manager_user_id, actor,
      correlation, 'assigned'
    );
  else
    if not exists (
      select 1 from app.manager_property_assignments
      where organization_id = organization
        and property_id = requested_property_id
        and manager_user_id = requested_manager_user_id
        and revoked_at is null
    ) then
      return false;
    end if;

    update app.manager_property_assignments
    set revoked_at = transaction_timestamp()
    where organization_id = organization
      and property_id = requested_property_id
      and manager_user_id = requested_manager_user_id
      and revoked_at is null;

    insert into app.manager_property_assignment_events (
      organization_id, property_id, manager_user_id, actor_id,
      correlation_id, action
    ) values (
      organization, requested_property_id, requested_manager_user_id, actor,
      correlation, 'revoked'
    );
  end if;

  insert into app.audit_events (
    organization_id, actor_id, correlation_id, action, entity_type, entity_id
  ) values (
    organization, actor, correlation,
    case when requested_assigned
      then 'manager_property_assigned'
      else 'manager_property_revoked'
    end,
    'manager_property_assignment', requested_property_id
  );
  return true;
end
$$;

CREATE FUNCTION app.set_property_verification_status(requested_property_id uuid, requested_status text, requested_actor_user_id uuid) RETURNS TABLE(property_id uuid, verification_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  property_organization_id uuid;
  property_jurisdiction_code text;
begin
  if requested_property_id is null
    or requested_actor_user_id is null
    or requested_status is null
    or requested_status not in (
      'not_started', 'pending', 'changes_requested', 'verified',
      'rejected', 'expired', 'suspended'
    ) then
    raise exception 'valid property, status, and actor are required';
  end if;

  select organization_id, jurisdiction_code
  into property_organization_id, property_jurisdiction_code
  from app.properties
  where id = requested_property_id;

  if not found then
    return;
  end if;

  if requested_status = 'verified' then
    if property_jurisdiction_code is null then
      raise exception 'verified properties require a jurisdiction code';
    end if;

    if not exists (
      select 1
      from app.resolve_active_jurisdiction_policy(
        'property_verification',
        property_jurisdiction_code,
        transaction_timestamp()
      )
    ) then
      raise exception 'verified properties require an active jurisdiction policy';
    end if;
  end if;

  update app.properties
  set verification_status = requested_status,
    updated_at = transaction_timestamp(),
    version = version + 1
  where id = requested_property_id;

  insert into app.audit_events (
    organization_id,
    actor_id,
    correlation_id,
    action,
    entity_type,
    entity_id
  ) values (
    property_organization_id,
    requested_actor_user_id,
    coalesce(nullif(current_setting('app.correlation_id', true), ''), gen_random_uuid()::text),
    'property.verification_status_set',
    'property',
    requested_property_id
  );

  return query
  select requested_property_id, requested_status;
end
$$;

CREATE FUNCTION app.set_public_listing_publication(requested_listing_id uuid, requested_published boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := nullif(current_setting('app.correlation_id', true), '');
  listing app.public_listings%rowtype;
  assignment_event_id uuid;
  property_record app.properties%rowtype;
  unit_record app.units%rowtype;
  current_pricing record;
  current_availability record;
  listing_snapshot jsonb;
  event_action text;
  total_image_count integer;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  select candidate.* into listing
  from app.public_listings as candidate
  where candidate.id = requested_listing_id
    and candidate.organization_id = organization
  for update of candidate;

  if not found then
    return false;
  end if;

  select event.id into assignment_event_id
  from app.manager_property_assignment_events as event
  join app.memberships as membership
    on membership.organization_id = event.organization_id
   and membership.user_id = event.manager_user_id
  join app.manager_property_assignments as assignment
    on assignment.organization_id = event.organization_id
   and assignment.property_id = event.property_id
   and assignment.manager_user_id = event.manager_user_id
   and assignment.assigned_at = event.occurred_at
   and assignment.revoked_at is null
  where event.organization_id = organization
    and event.property_id = listing.property_id
    and event.manager_user_id = actor
    and event.action = 'assigned'
    and membership.role in ('landlord', 'manager')
    and membership.active
    and membership.effective_from <= transaction_timestamp()
    and (membership.effective_to is null or transaction_timestamp() < membership.effective_to)
  order by event.occurred_at desc, event.id desc
  limit 1;

  if assignment_event_id is null then
    return false;
  end if;

  if requested_published then
    if listing.status = 'published' then
      return false;
    end if;

    select * into property_record
    from app.properties
    where organization_id = organization
      and id = listing.property_id;
    select * into unit_record
    from app.units
    where organization_id = organization
      and id = listing.unit_id
      and property_id = listing.property_id;

    if not found
      or property_record.archived_at is not null
      or property_record.verification_status in ('rejected', 'expired', 'suspended')
      or property_record.publication_status not in ('draft', 'pending_review', 'paused')
      or unit_record.archived_at is not null
      or unit_record.publication_status <> 'published' then
      return false;
    end if;

    select pricing.id, pricing.amount_minor, pricing.currency into current_pricing
    from app.unit_pricing_versions as pricing
    where pricing.organization_id = organization
      and pricing.unit_id = listing.unit_id
      and pricing.effective_from <= transaction_timestamp()
      and (pricing.effective_to is null or transaction_timestamp() < pricing.effective_to)
    order by pricing.effective_from desc, pricing.id desc
    limit 1;

    select availability.id, availability.status, availability.effective_from into current_availability
    from app.unit_availability_versions as availability
    where availability.organization_id = organization
      and availability.unit_id = listing.unit_id
      and availability.effective_from <= transaction_timestamp()
      and (availability.effective_to is null or transaction_timestamp() < availability.effective_to)
    order by availability.effective_from desc, availability.id desc
    limit 1;

    if current_pricing.id is null or current_availability.id is null or current_availability.status <> 'available' then
      return false;
    end if;

    select app.count_public_listing_images(organization, listing.id) into total_image_count;
    if total_image_count < 1 then
      return false;
    end if;
    if listing.media_review_status <> 'approved' then
      return false;
    end if;

    listing_snapshot := jsonb_build_object(
      'propertyId', listing.property_id,
      'propertyVersion', property_record.version,
      'unitId', listing.unit_id,
      'unitVersion', unit_record.version,
      'pricingVersionId', current_pricing.id,
      'availabilityVersionId', current_availability.id,
      'projection', jsonb_build_object(
        'id', listing.id::text,
        'name', coalesce(listing.title, property_record.name || ' — ' || unit_record.label),
        'summary', coalesce(listing.snapshot -> 'projection' ->> 'summary', property_record.name || ' listing'),
        'city', property_record.address ->> 'city',
        'district', property_record.address ->> 'quartier',
        'bedrooms', unit_record.bedrooms,
        'bathrooms', unit_record.bathrooms,
        'monthlyRentMinor', current_pricing.amount_minor::text,
        'currency', current_pricing.currency,
        'availableFrom', (current_availability.effective_from at time zone 'UTC')::date,
        'amenities', coalesce(listing.snapshot -> 'projection' -> 'amenities', '[]'::jsonb),
        'imageUrls', coalesce(listing.snapshot -> 'projection' -> 'imageUrls', '[]'::jsonb),
        'areaSquareMeters', unit_record.area_square_meters
      )
    );

    update app.public_listings
    set status = 'published',
        snapshot = listing_snapshot,
        version = version + 1,
        published_at = transaction_timestamp(),
        withdrawn_at = null,
        updated_at = transaction_timestamp()
    where id = listing.id;
    event_action := 'published';
  else
    if listing.status <> 'published' then
      return false;
    end if;

    update app.public_listings
    set status = 'withdrawn',
        version = version + 1,
        withdrawn_at = transaction_timestamp(),
        updated_at = transaction_timestamp()
    where id = listing.id;
    event_action := 'withdrawn';
  end if;

  insert into app.public_listing_publication_events (
    organization_id, listing_id, property_id, unit_id, actor_id,
    manager_assignment_event_id, manager_assignment_action, listing_version,
    correlation_id, action, source, occurred_at
  ) values (
    organization, listing.id, listing.property_id, listing.unit_id, actor,
    assignment_event_id, 'assigned', listing.version + 1,
    correlation, event_action, 'runtime_api', transaction_timestamp()
  );

  return true;
end
$$;

CREATE FUNCTION app.set_unit_availability(requested_unit_id uuid, requested_status text, requested_reason_code text, requested_effective_from timestamp with time zone, requested_expected_version integer, requested_idempotency_key text, requested_correlation_id text, requested_source text) RETURNS TABLE(availability_version_id uuid, unit_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := coalesce(requested_correlation_id, nullif(current_setting('app.correlation_id', true), ''));
  unit_record app.units%rowtype;
  new_id uuid;
  is_occupied boolean;
  derived_status text;
  payload jsonb;
  replay record;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  select * into unit_record
  from app.units
  where organization_id = organization and id = requested_unit_id
  for update;

  if not found or unit_record.archived_at is not null then
    raise exception 'the requested Unit was not found' using errcode = 'P0002';
  end if;

  if not app.actor_can_manage_property(organization, unit_record.property_id, actor) then
    raise exception 'the actor is not authorized to manage this Unit' using errcode = '42501';
  end if;

  -- Idempotency-key replay (PROP-014): resolved only after the current
  -- actor's authorization is confirmed above (see set_unit_pricing).
  payload := jsonb_build_object(
    'unitId', requested_unit_id, 'status', requested_status,
    'reasonCode', requested_reason_code, 'effectiveFrom', requested_effective_from,
    'expectedVersion', requested_expected_version
  );

  select * into replay from app.resolve_rental_inventory_creation_replay(
    organization, actor, 'set_unit_availability', requested_idempotency_key, payload
  );

  if replay.is_replay then
    availability_version_id := (replay.replay_result ->> 'availabilityVersionId')::uuid;
    unit_version := (replay.replay_result ->> 'unitVersion')::integer;
    return next;
    return;
  end if;

  if unit_record.version <> requested_expected_version then
    raise exception 'the supplied version is stale' using errcode = '40001';
  end if;

  update app.unit_availability_versions
  set effective_to = requested_effective_from
  where organization_id = organization
    and unit_id = requested_unit_id
    and effective_to is null;

  insert into app.unit_availability_versions (
    organization_id, unit_id, status, reason_code, effective_from, created_by,
    correlation_id, source
  ) values (
    organization, requested_unit_id, requested_status, requested_reason_code,
    requested_effective_from, actor, correlation, requested_source
  ) returning id into new_id;

  select exists (
    select 1 from app.leases
    where organization_id = organization and unit_id = requested_unit_id
      and accepted_at is not null and archived_at is null
  ) into is_occupied;

  derived_status := case when is_occupied then 'occupied' else requested_status end;

  update app.units
  set availability_status = derived_status,
      version = version + 1,
      updated_at = transaction_timestamp()
  where organization_id = organization and id = requested_unit_id
  returning version into unit_version;

  perform app.record_rental_inventory_event(
    organization, 'availability_version', new_id, 1, actor, correlation,
    'availability.set', null, requested_source
  );

  availability_version_id := new_id;

  perform app.record_rental_inventory_creation_replay(
    organization, actor, 'set_unit_availability', requested_idempotency_key, payload,
    jsonb_build_object('availabilityVersionId', availability_version_id, 'unitVersion', unit_version)
  );

  return next;
end
$$;

CREATE FUNCTION app.set_unit_pricing(requested_unit_id uuid, requested_amount_minor bigint, requested_currency character, requested_effective_from timestamp with time zone, requested_expected_version integer, requested_idempotency_key text, requested_correlation_id text, requested_source text) RETURNS TABLE(pricing_version_id uuid, unit_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := coalesce(requested_correlation_id, nullif(current_setting('app.correlation_id', true), ''));
  unit_record app.units%rowtype;
  new_id uuid;
  payload jsonb;
  replay record;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  select * into unit_record
  from app.units
  where organization_id = organization and id = requested_unit_id
  for update;

  if not found or unit_record.archived_at is not null then
    raise exception 'the requested Unit was not found' using errcode = 'P0002';
  end if;

  if not app.actor_can_manage_property(organization, unit_record.property_id, actor) then
    raise exception 'the actor is not authorized to manage this Unit' using errcode = '42501';
  end if;

  -- Idempotency-key replay (PROP-014): resolved only after the current
  -- actor's authorization is confirmed above, so a caller whose membership
  -- or property assignment has since been revoked cannot replay a cached
  -- result they are no longer authorized to see.
  payload := jsonb_build_object(
    'unitId', requested_unit_id, 'amountMinor', requested_amount_minor,
    'currency', requested_currency, 'effectiveFrom', requested_effective_from,
    'expectedVersion', requested_expected_version
  );

  select * into replay from app.resolve_rental_inventory_creation_replay(
    organization, actor, 'set_unit_pricing', requested_idempotency_key, payload
  );

  if replay.is_replay then
    pricing_version_id := (replay.replay_result ->> 'pricingVersionId')::uuid;
    unit_version := (replay.replay_result ->> 'unitVersion')::integer;
    return next;
    return;
  end if;

  if unit_record.version <> requested_expected_version then
    raise exception 'the supplied version is stale' using errcode = '40001';
  end if;

  update app.unit_pricing_versions
  set effective_to = requested_effective_from
  where organization_id = organization
    and unit_id = requested_unit_id
    and effective_to is null;

  insert into app.unit_pricing_versions (
    organization_id, unit_id, amount_minor, currency, billing_period,
    effective_from, created_by, correlation_id, source
  ) values (
    organization, requested_unit_id, requested_amount_minor, requested_currency,
    'month', requested_effective_from, actor, correlation, requested_source
  ) returning id into new_id;

    update app.units
  set version = version + 1, updated_at = transaction_timestamp()
  where organization_id = organization and id = requested_unit_id
  returning version into unit_version;

  perform app.record_rental_inventory_event(
    organization, 'pricing_version', new_id, 1, actor, correlation,
    'pricing.set', null, requested_source
  );

  pricing_version_id := new_id;

  perform app.record_rental_inventory_creation_replay(
    organization, actor, 'set_unit_pricing', requested_idempotency_key, payload,
    jsonb_build_object('pricingVersionId', pricing_version_id, 'unitVersion', unit_version)
  );

  return next;
end
$$;

CREATE FUNCTION app.submit_landlord_onboarding_application(requested_applicant_subject text, requested_applicant_object_id uuid, requested_applicant_name text, requested_organization_name text, requested_correlation_id text) RETURNS SETOF app.landlord_onboarding_applications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  application app.landlord_onboarding_applications%rowtype;
begin
  perform pg_advisory_xact_lock(hashtextextended(requested_applicant_object_id::text, 0));

  if exists (
    select 1 from app.landlord_onboarding_applications
    where applicant_object_id = requested_applicant_object_id
  ) then
    return;
  end if;

  insert into app.landlord_onboarding_applications (
    applicant_subject, applicant_object_id, applicant_name,
    proposed_organization_name, submitted_correlation_id
  ) values (
    btrim(requested_applicant_subject), requested_applicant_object_id,
    btrim(requested_applicant_name), btrim(requested_organization_name),
    requested_correlation_id
  ) returning * into application;

  return next application;
end
$$;

CREATE FUNCTION app.sync_membership_party() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
begin
  select users.party_id into new.party_id
  from app.users
  where users.id = new.user_id;

  if new.party_id is null then
    raise exception 'membership user must resolve to a party';
  end if;
  if new.effective_from is null then
    new.effective_from := now();
  end if;
  return new;
end
$$;

CREATE FUNCTION app.sync_user_identity_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
begin
  insert into app.profiles (party_id, profile_type, display_name)
  values (new.party_id, 'identity', new.display_name)
  on conflict (party_id, profile_type) do update
    set display_name = excluded.display_name,
        updated_at = now(),
        version = app.profiles.version + 1;
  return new;
end
$$;

CREATE FUNCTION app.update_public_listing_draft(requested_listing_id uuid, requested_title text, requested_summary text, requested_image_urls jsonb, requested_expected_version integer, requested_correlation_id text, requested_source text) RETURNS TABLE(listing_id uuid, listing_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := coalesce(requested_correlation_id, nullif(current_setting('app.correlation_id', true), ''));
  listing app.public_listings%rowtype;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  select * into listing
  from app.public_listings
  where organization_id = organization and id = requested_listing_id
  for update;

  if not found then
    return;
  end if;

  if not app.actor_can_manage_property(organization, listing.property_id, actor) then
    raise exception 'only an active listing-manager assignment may edit this PublicListing'
      using errcode = '42501';
  end if;

  if listing.status <> 'draft' then
    raise exception 'only a draft PublicListing may be edited' using errcode = '23514';
  end if;

  if listing.version <> requested_expected_version then
    raise exception 'the supplied version is stale' using errcode = '40001';
  end if;

  perform app.validate_public_listing_media_payload(
    requested_title, requested_summary, requested_image_urls
  );

  update app.public_listings
  set title = requested_title,
      media_review_status = 'pending',
      media_reviewed_at = null,
      media_reviewer_subject = null,
      media_reviewer_object_id = null,
      media_review_notes = null,
      snapshot = jsonb_build_object('projection', jsonb_build_object(
        'title', requested_title, 'summary', requested_summary, 'imageUrls', requested_image_urls
      )),
      version = version + 1,
      updated_at = transaction_timestamp()
  where id = listing.id
  returning id, version into listing_id, listing_version;

  perform app.record_rental_inventory_event(
    organization, 'public_listing', listing_id, listing_version,
    actor, correlation, 'listing.updated', 'Draft PublicListing edited and resubmitted for media review',
    requested_source
  );

  return next;
end
$$;

CREATE FUNCTION app.upload_public_listing_image(requested_listing_id uuid, requested_room text, requested_media_type text, requested_size_bytes integer, requested_content bytea, requested_content_hash text, requested_correlation_id text, requested_source text) RETURNS TABLE(image_id uuid, listing_id uuid, listing_version integer, image_position integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
declare
  organization uuid := app.current_organization_id();
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  correlation text := coalesce(requested_correlation_id, nullif(current_setting('app.correlation_id', true), ''));
  listing app.public_listings%rowtype;
  existing_count integer;
  next_position integer;
  inserted app.public_listing_images%rowtype;
  updated_version integer;
begin
  if organization is null or actor is null or correlation is null then
    raise exception 'trusted request context is required';
  end if;

  perform app.validate_public_listing_image_upload(
    requested_room, requested_media_type, requested_size_bytes
  );

  if requested_content is null or octet_length(requested_content) <> requested_size_bytes then
    raise exception 'the uploaded image content does not match the declared size' using errcode = '23514';
  end if;

  select * into listing
  from app.public_listings
  where organization_id = organization and id = requested_listing_id
  for update;

  if not found then
    return;
  end if;

  if not app.actor_can_manage_property(organization, listing.property_id, actor) then
    raise exception 'only an active listing-manager assignment may upload media for this PublicListing'
      using errcode = '42501';
  end if;

  if listing.status not in ('draft', 'withdrawn') then
    raise exception 'only a draft or withdrawn PublicListing may receive uploaded images' using errcode = '23514';
  end if;

  select app.count_public_listing_images(organization, requested_listing_id) into existing_count;
  if existing_count >= 10 then
    raise exception 'a PublicListing may have at most 10 images' using errcode = '23514';
  end if;

  select coalesce(max(position) + 1, 0) into next_position
  from app.public_listing_images
  where organization_id = organization and public_listing_id = requested_listing_id and deleted_at is null;

  insert into app.public_listing_images (
    organization_id, public_listing_id, room, media_type, size_bytes, content,
    content_hash, position
  ) values (
    organization, requested_listing_id, requested_room, requested_media_type,
    requested_size_bytes, requested_content, requested_content_hash, next_position
  ) returning * into inserted;

  update app.public_listings
  set media_review_status = 'pending',
      media_reviewed_at = null,
      media_reviewer_subject = null,
      media_reviewer_object_id = null,
      media_review_notes = null,
      version = version + 1,
      updated_at = transaction_timestamp()
  where id = listing.id
  returning version into updated_version;

  perform app.record_rental_inventory_event(
    organization, 'public_listing', listing.id, updated_version,
    actor, correlation, 'listing.image_uploaded',
    'An image was uploaded and the listing resubmitted for media review',
    requested_source
  );

  image_id := inserted.id;
  listing_id := listing.id;
  listing_version := updated_version;
  image_position := inserted.position;
  return next;
end
$$;

CREATE FUNCTION app.validate_public_listing_image_upload(requested_room text, requested_media_type text, requested_size_bytes integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  if requested_room is null or requested_room not in
    ('exterior', 'living', 'kitchen', 'bathroom', 'bedroom', 'dining', 'other') then
    raise exception 'a room tag is required and must be one of the approved categories'
      using errcode = '23514';
  end if;
  if requested_media_type is null or requested_media_type not in ('image/jpeg', 'image/png') then
    raise exception 'only JPEG or PNG images may be uploaded' using errcode = '23514';
  end if;
  if requested_size_bytes is null or requested_size_bytes < 1 or requested_size_bytes > 10485760 then
    raise exception 'an uploaded image must be between 1 byte and 10 MB' using errcode = '23514';
  end if;
end
$$;

CREATE FUNCTION app.validate_public_listing_media_payload(requested_title text, requested_summary text, requested_image_urls jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $_$
declare
  url_count integer;
  distinct_url_count integer;
  invalid_url_count integer;
begin
  if requested_title is null or char_length(btrim(requested_title)) not between 3 and 140 then
    raise exception 'a listing title between 3 and 140 characters is required' using errcode = '23514';
  end if;
  if requested_summary is null or char_length(btrim(requested_summary)) not between 10 and 4000 then
    raise exception 'a listing summary between 10 and 4000 characters is required' using errcode = '23514';
  end if;
  if requested_image_urls is null or jsonb_typeof(requested_image_urls) <> 'array' then
    raise exception 'imageUrls must be a JSON array' using errcode = '23514';
  end if;

  select count(*) into url_count from jsonb_array_elements_text(requested_image_urls);
  select count(distinct value) into distinct_url_count from jsonb_array_elements_text(requested_image_urls);
  select count(*) into invalid_url_count
  from jsonb_array_elements_text(requested_image_urls) as value
  where value !~ '^https://\S+$' or char_length(value) > 2048;

  if url_count > 10 then
    raise exception 'a listing may have at most 10 image URLs' using errcode = '23514';
  end if;
  if distinct_url_count <> url_count then
    raise exception 'image URLs must be unique' using errcode = '23514';
  end if;
  if invalid_url_count > 0 then
    raise exception 'every image URL must be an https:// URL of at most 2048 characters'
      using errcode = '23514';
  end if;
end
$_$;

