CREATE TABLE app.properties (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    name text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    archived_at timestamp with time zone,
    verification_status text DEFAULT 'not_started'::text NOT NULL,
    publication_status text DEFAULT 'draft'::text NOT NULL,
    property_type text NOT NULL,
    address jsonb NOT NULL,
    time_zone text NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    archived_by uuid,
    archive_reason text,
    jurisdiction_code text,
    CONSTRAINT properties_address_check CHECK (((jsonb_typeof(address) = 'object'::text) AND (address ?& ARRAY['avenueOrStreet'::text, 'number'::text, 'quartier'::text, 'commune'::text, 'city'::text, 'province'::text, 'countryCode'::text]) AND ((address - ARRAY['avenueOrStreet'::text, 'number'::text, 'quartier'::text, 'commune'::text, 'city'::text, 'province'::text, 'countryCode'::text, 'postalCode'::text]) = '{}'::jsonb) AND (jsonb_typeof((address -> 'avenueOrStreet'::text)) = 'string'::text) AND ((char_length(btrim((address ->> 'avenueOrStreet'::text))) >= 1) AND (char_length(btrim((address ->> 'avenueOrStreet'::text))) <= 160)) AND ((address ->> 'avenueOrStreet'::text) = btrim((address ->> 'avenueOrStreet'::text))) AND (jsonb_typeof((address -> 'number'::text)) = 'string'::text) AND ((char_length(btrim((address ->> 'number'::text))) >= 1) AND (char_length(btrim((address ->> 'number'::text))) <= 160)) AND ((address ->> 'number'::text) = btrim((address ->> 'number'::text))) AND (jsonb_typeof((address -> 'quartier'::text)) = 'string'::text) AND ((char_length(btrim((address ->> 'quartier'::text))) >= 1) AND (char_length(btrim((address ->> 'quartier'::text))) <= 160)) AND ((address ->> 'quartier'::text) = btrim((address ->> 'quartier'::text))) AND (jsonb_typeof((address -> 'commune'::text)) = 'string'::text) AND ((char_length(btrim((address ->> 'commune'::text))) >= 1) AND (char_length(btrim((address ->> 'commune'::text))) <= 160)) AND ((address ->> 'commune'::text) = btrim((address ->> 'commune'::text))) AND (jsonb_typeof((address -> 'city'::text)) = 'string'::text) AND ((char_length(btrim((address ->> 'city'::text))) >= 1) AND (char_length(btrim((address ->> 'city'::text))) <= 160)) AND ((address ->> 'city'::text) = btrim((address ->> 'city'::text))) AND (jsonb_typeof((address -> 'province'::text)) = 'string'::text) AND ((char_length(btrim((address ->> 'province'::text))) >= 1) AND (char_length(btrim((address ->> 'province'::text))) <= 160)) AND ((address ->> 'province'::text) = btrim((address ->> 'province'::text))) AND (jsonb_typeof((address -> 'countryCode'::text)) = 'string'::text) AND ((address ->> 'countryCode'::text) ~ '^[A-Z]{2}$'::text) AND ((NOT (address ? 'postalCode'::text)) OR ((jsonb_typeof((address -> 'postalCode'::text)) = 'string'::text) AND ((char_length(btrim((address ->> 'postalCode'::text))) >= 1) AND (char_length(btrim((address ->> 'postalCode'::text))) <= 160)) AND ((address ->> 'postalCode'::text) = btrim((address ->> 'postalCode'::text))))))),
    CONSTRAINT properties_archive_metadata_check CHECK ((((archived_at IS NULL) AND (archived_by IS NULL) AND (archive_reason IS NULL) AND (publication_status <> 'archived'::text)) OR ((archived_at IS NOT NULL) AND (archived_by IS NOT NULL) AND ((char_length(btrim(archive_reason)) >= 1) AND (char_length(btrim(archive_reason)) <= 1000)) AND (publication_status = 'archived'::text)))),
    CONSTRAINT properties_jurisdiction_code_check CHECK (((jurisdiction_code IS NULL) OR (jurisdiction_code ~ '^[A-Z]{2}(-[A-Z0-9]{1,6})?$'::text))),
    CONSTRAINT properties_name_check CHECK ((((char_length(name) >= 1) AND (char_length(name) <= 160)) AND (name = btrim(name)))),
    CONSTRAINT properties_publication_status_check CHECK ((publication_status = ANY (ARRAY['draft'::text, 'pending_review'::text, 'paused'::text, 'archived'::text]))),
    CONSTRAINT properties_time_zone_check CHECK (((char_length(btrim(time_zone)) >= 1) AND (char_length(btrim(time_zone)) <= 100))),
    CONSTRAINT properties_type_check CHECK ((property_type = ANY (ARRAY['apartment_building'::text, 'single_family'::text, 'townhouse'::text, 'mixed_use'::text, 'other'::text]))),
    CONSTRAINT properties_verification_status_check CHECK ((verification_status = ANY (ARRAY['not_started'::text, 'pending'::text, 'changes_requested'::text, 'verified'::text, 'rejected'::text, 'expired'::text, 'suspended'::text]))),
    CONSTRAINT properties_version_check CHECK ((version > 0))
);

