    CONSTRAINT rental_inventory_creation_replays_idempotency_key_check CHECK (((char_length(btrim(idempotency_key)) >= 1) AND (char_length(btrim(idempotency_key)) <= 128))),
    CONSTRAINT rental_inventory_creation_replays_operation_check CHECK (((char_length(btrim(operation)) >= 1) AND (char_length(btrim(operation)) <= 64))),
    CONSTRAINT rental_inventory_creation_replays_payload_hash_check CHECK ((char_length(payload_hash) = 64))
);

CREATE TABLE app.rental_inventory_events (
