    CONSTRAINT rental_inventory_events_action_check CHECK (((char_length(btrim(action)) >= 1) AND (char_length(btrim(action)) <= 100))),
    CONSTRAINT rental_inventory_events_aggregate_type_check CHECK ((aggregate_type = ANY (ARRAY['property'::text, 'unit'::text, 'pricing_version'::text, 'availability_version'::text, 'public_listing'::text]))),
    CONSTRAINT rental_inventory_events_aggregate_version_check CHECK ((aggregate_version > 0)),
    CONSTRAINT rental_inventory_events_correlation_id_check CHECK (((char_length(btrim(correlation_id)) >= 1) AND (char_length(btrim(correlation_id)) <= 128))),
    CONSTRAINT rental_inventory_events_reason_check CHECK (((reason IS NULL) OR ((char_length(btrim(reason)) >= 1) AND (char_length(btrim(reason)) <= 1000)))),
    CONSTRAINT rental_inventory_events_source_check CHECK (((char_length(btrim(source)) >= 1) AND (char_length(btrim(source)) <= 64)))
);

ALTER TABLE ONLY app.rental_inventory_events FORCE ROW LEVEL SECURITY;

CREATE TABLE app.tenant_application_documents (
