    CONSTRAINT tenant_application_documents_file_name_check CHECK (((length(TRIM(BOTH FROM file_name)) >= 1) AND (length(TRIM(BOTH FROM file_name)) <= 255))),
    CONSTRAINT tenant_application_documents_size_bytes_check CHECK (((size_bytes >= 1) AND (size_bytes <= 10485760))),
    CONSTRAINT tenant_application_documents_version_check CHECK ((version > 0))
);

ALTER TABLE ONLY app.tenant_application_documents FORCE ROW LEVEL SECURITY;

