CREATE TABLE app.tenant_applications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    tenant_user_id uuid NOT NULL,
    identity jsonb NOT NULL,
    household_members jsonb NOT NULL,
    employment jsonb NOT NULL,
    current_housing jsonb NOT NULL,
    emergency_contact jsonb NOT NULL,
    desired_move_in_date date NOT NULL,
    occupants integer NOT NULL,
    pets text,
    notes text,
    declarations jsonb NOT NULL,
    evidence text[] DEFAULT ARRAY['identity'::text, 'income'::text, 'address'::text, 'reference'::text] NOT NULL,
    status app.tenant_application_status DEFAULT 'draft'::app.tenant_application_status NOT NULL,
    submitted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tenant_applications_employment_check CHECK (((employment ->> 'monthlyIncomeMinor'::text) ~ '^\d+$'::text)),
    CONSTRAINT tenant_applications_employment_check1 CHECK (((employment ->> 'currency'::text) ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT tenant_applications_household_members_check CHECK ((jsonb_typeof(household_members) = 'array'::text)),
    CONSTRAINT tenant_applications_occupants_check CHECK (((occupants >= 1) AND (occupants <= 30))),
    CONSTRAINT tenant_applications_status_submission_check CHECK ((((status = 'draft'::app.tenant_application_status) AND (submitted_at IS NULL)) OR ((status = ANY (ARRAY['submitted'::app.tenant_application_status, 'approved'::app.tenant_application_status, 'declined'::app.tenant_application_status])) AND (submitted_at IS NOT NULL)))),
    CONSTRAINT tenant_applications_version_check CHECK ((version > 0))
);

