CREATE TABLE app.units (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    property_id uuid NOT NULL,
    label text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    archived_at timestamp with time zone,
    publication_status text DEFAULT 'draft'::text NOT NULL,
    availability_status text DEFAULT 'unavailable'::text NOT NULL,
    canonical_label text NOT NULL,
    unit_type text NOT NULL,
    bedrooms smallint NOT NULL,
    bathrooms smallint NOT NULL,
    area_square_meters integer,
    floor_label text,
    furnishing_status text NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    archived_by uuid,
    archive_reason text,
    CONSTRAINT units_archive_metadata_check CHECK ((((archived_at IS NULL) AND (archived_by IS NULL) AND (archive_reason IS NULL) AND (publication_status <> 'archived'::text)) OR ((archived_at IS NOT NULL) AND (archived_by IS NOT NULL) AND ((char_length(btrim(archive_reason)) >= 1) AND (char_length(btrim(archive_reason)) <= 1000)) AND (publication_status = 'archived'::text)))),
    CONSTRAINT units_area_check CHECK (((area_square_meters IS NULL) OR ((area_square_meters >= 1) AND (area_square_meters <= 100000)))),
    CONSTRAINT units_availability_status_check CHECK ((availability_status = ANY (ARRAY['unavailable'::text, 'available'::text, 'occupied'::text]))),
    CONSTRAINT units_bathrooms_check CHECK (((bathrooms >= 1) AND (bathrooms <= 20))),
    CONSTRAINT units_bedrooms_check CHECK (((bedrooms >= 0) AND (bedrooms <= 20))),
    CONSTRAINT units_canonical_label_check CHECK ((((char_length(canonical_label) >= 1) AND (char_length(canonical_label) <= 320)) AND (canonical_label !~ '^[[:space:]]*$'::text))),
    CONSTRAINT units_floor_label_check CHECK (((floor_label IS NULL) OR (((char_length(btrim(floor_label)) >= 1) AND (char_length(btrim(floor_label)) <= 40)) AND (floor_label = btrim(floor_label))))),
    CONSTRAINT units_furnishing_status_check CHECK ((furnishing_status = ANY (ARRAY['unfurnished'::text, 'part_furnished'::text, 'furnished'::text]))),
    CONSTRAINT units_label_check CHECK ((((char_length(label) >= 1) AND (char_length(label) <= 80)) AND (label = btrim(label)))),
    CONSTRAINT units_publication_status_check CHECK ((publication_status = ANY (ARRAY['draft'::text, 'pending_review'::text, 'published'::text, 'paused'::text, 'archived'::text]))),
    CONSTRAINT units_type_check CHECK ((unit_type = ANY (ARRAY['studio'::text, 'apartment'::text, 'house'::text, 'townhouse'::text, 'commercial'::text, 'other'::text]))),
    CONSTRAINT units_version_check CHECK ((version > 0))
);

